const top_pantheon = {
  champion: '판테온',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (Q)\'혜성의 창\'을 활용해 가렌의 체력을 깎으며 거리를 조절하세요. 가렌이 (Q)\'결정타\'로 달려들면 (E)\'방패 돌격\'을 사용해 피해를 최소화하며 대응해야 해요. 가렌이 (P)\'인내심\'으로 체력을 빠르게 채우지 못하도록 짧은 딜교환을 반복하세요.', lv3: '가렌이 (Q)\'결정타\'를 써서 침묵을 걸기 전에 (W)\'방호의 도약\'으로 먼저 기절을 시키는 것이 좋아요. 가렌이 (E)\'심판\'을 돌리며 들어올 때는 (E)\'방패 돌격\'으로 정면 공격을 막아내며 버티세요. 가렌이 (W)\'용기\'로 보호막을 켰을 때는 무리하게 싸우지 말고 (Q)\'혜성의 창\'을 아껴두세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮을 때 매우 위협적이니 항상 체력을 일정 수준 이상 유지하세요. (R)\'거대 유성\'을 사용해 적절한 위치에서 싸움을 시작하거나 위험할 때 거리를 벌리세요. 가렌이 (E)\'심판\'으로 계속 압박하면 라인을 당겨 받으며 정글러의 도움을 기다려야 해요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 가렌의 기본 공격 피해를 줄여주며 갈라진 하늘은 전투에서 체력을 유지하기 좋기 때문이에요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복량을 줄여야 킬을 따내기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 거리를 조심하며 미니언을 챙기세요. (Q)\'혀어어어업상\'은 대상을 직접 지정해 쏘는 기술이라 미니언 뒤에 숨어도 피할 수 없으니 주의가 필요해요. (Q)\'혜성의 창\'을 활용해 짧게 찌르며 갱플랭크의 체력을 깎고 근접전을 준비하세요.', lv3: '갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하고 군중 제어를 풀 수 있으니 이 스킬을 먼저 쓰게 유도하세요. (E)\'화약통\'이 깔린 곳 근처에서는 싸움을 피하고 (W)\'방호의 도약\'으로 진입할 때 통이 터지지 않는 방향을 잘 잡으세요. (W)\'방호의 도약\'으로 기절을 시킨 뒤 (Q)\'혜성의 창\'을 맞춰서 딜교환을 이어나가세요.', lv6: '갱플랭크가 (W)\'괴혈병 치료\'를 쓴 직후라 회복과 군중 제어 해제가 빠진 상태라면 (R)\'거대 유성\'으로 빠르게 진입해 (W)\'방호의 도약\'과 함께 몰아치세요. (R)\'포탄 세례\'가 떨어지는 구역은 이동 속도가 느려져 도망치기 힘드니 미리 위치를 확인하며 움직이세요. 라인을 강하게 밀어넣어 갱플랭크가 (R)\'포탄 세례\'를 사용하는 타이밍에 정글러와 함께 압박하세요.', item: '갈라진 하늘을 첫 코어로 올려 교전 중 체력을 회복하고 순간적인 피해를 입히세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 좋아요. 다만 판금 장화는 (R)\'포탄 세례\' 같은 스킬 피해는 줄여주지 못해요.', spell: '점멸과 점화를 추천해요. 갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하며 버티는 것을 막고 킬을 확실히 따낼 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화와 견제를 넣으며 (P)\'서비스 시간\'으로 체력을 회복해요. (Q)\'혜성의 창\'으로 맞대응하되 술통이 터지는 위치를 피해 막타를 챙기세요. 그라가스가 스킬을 사용하여 체력을 돌려받는 구간에는 무리하게 맞서기보다 거리를 유지하며 체력을 관리해요.', lv3: '(E)\'몸통 박치기\'에 맞아 공중으로 떠오르면 흐름이 끊기니 이 스킬이 빠진 것을 확인하고 진입하세요. 그라가스가 (W)\'취중 분노\'를 켜면 받는 피해가 줄어드니 (W)\'방호의 도약\'으로 기절을 시킨 뒤 (Q)\'혜성의 창\'을 맞히는 것이 좋아요. (E)\'방패 돌격\'으로 그라가스의 공격을 막으며 딜교환을 시작하세요.', lv6: '(R)\'거대 유성\'을 사용해 진입한 뒤 (W)\'방호의 도약\'으로 빠르게 붙어 킬각을 잡으세요. 그라가스가 (R)\'술통 폭발\'로 밀어낼 수 있으니 폭발 중심에서 벗어나는 방향으로 움직여야 해요. 정글러를 부를 때 (R)\'거대 유성\'으로 합류하거나 시야를 확보하며 라인을 관리하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 동시에 챙기세요. 신발은 그라가스의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요. (Q)\'술통 굴리기\'의 둔화 지속시간도 강인함으로 줄일 수 있어요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 체력 회복 효과를 점화로 줄여 킬을 내기 쉽게 만드세요.' },
    '그웬': { lv1: '1~2레벨에는 (Q)\'혜성의 창\'을 활용해 짧게 찌르고 빠지며 그웬의 체력을 깎아 두세요. 그웬은 (P)\'가위 난도질\' 중첩을 쌓아 (Q)\'싹둑싹둑!\'을 쓰면 회복량이 많으니 길게 싸워주면 안 돼요. 미니언 사이에서 (Q)\'혜성의 창\'으로 견제하며 그웬이 평타로 가위질 중첩을 쌓지 못하게 하세요.', lv3: '그웬이 (W)\'신성한 안개\'를 켜면 대상 지정이 불가능하니 (W)\'방호의 도약\'을 바로 쓰지 말고 안개가 사라진 후에 사용하세요. (E)\'방패 돌격\'은 범위 스킬인 (Q)\'싹둑싹둑!\'의 피해를 막을 수 있으니 타이밍을 잘 맞춰야 해요. (E)\'돌격가위\'로 들어오는 타이밍에 맞춰 (W)\'방호의 도약\'을 써서 기절을 시키세요.', lv6: '(R)\'거대 유성\'을 사용하여 그웬의 체력이 낮을 때 빠르게 진입해 처치할 수 있어요. 그웬이 (R)\'바느질\'로 둔화를 걸더라도 (E)\'방패 돌격\'으로 정면 피해를 막으며 버티고 싸우세요. 다만 (W)\'신성한 안개\' 안에 있는 그웬에게는 (W)\'방호의 도약\'을 쓸 수 없으니 안개가 끝난 뒤나 정글러가 왔을 때 몰아치세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 헤르메스의 발걸음은 마법 저항력을 제공하며, 맬모셔스의 아귀는 마법 저항력과 생명선 효과로 버티게 도와줘요.', spell: '점멸과 점화를 추천해요. 그웬은 (P)\'가위 난도질\'로 체력을 회복하니 점화로 회복 효과를 줄여야 해요.' },
    '나르': { lv1: '나르가 (Q)\'부메랑 던지기\'로 둔화를 걸며 멀리서 견제하니 부메랑 궤적을 피하며 거리를 조절하세요. (Q)\'혜성의 창\'을 짧게 사용하여 미니언과 함께 나르의 체력을 깎으며 첫 웨이브 소모전을 준비해요. 나르의 (W)\'슝슝\' 추가 피해를 맞지 않도록 평타를 짧게 치고 바로 빠지는 것이 좋아요.', lv3: '나르의 분노가 차서 메가 나르로 변신하면 (W)\'쿵쾅\'의 기절을 조심하며 거리를 두세요. 미니 나르일 때는 (W)\'방호의 도약\'으로 진입한 뒤 (Q)\'혜성의 창\'을 연계하여 딜교환을 하세요. 나르가 (E)\'폴짝\'으로 도망가려 할 때 (W)\'방호의 도약\'을 먼저 맞춰 기절시키는 것이 중요해요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절을 유발하니 벽 근처에서 싸우는 것을 피하세요. 분노가 가득 찬 나르와는 싸움을 피하고, 미니 나르로 돌아온 타이밍에 (R)\'거대 유성\'으로 진입해 둔화를 걸고 압박하세요. 정글러가 오면 나르가 (E)\'폴짝\'을 쓰기 전에 (W)\'방호의 도약\'으로 기절을 넣어 도주를 막으세요.', item: '갈라진 하늘과 판금 장화를 추천해요. 나르의 기본 공격 피해를 줄이며 전투를 이어가기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화로 나르의 체력을 낮춰 변신 전 짧은 타이밍에 처치하기 위해서예요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 미니언을 먹으며 성장하는 구간이라 초반에는 압박을 주는 것이 좋아요. (Q)\'혜성의 창\'을 활용해 나서스가 미니언을 편하게 챙기지 못하도록 견제하며 주도권을 가져오세요.', lv3: '나서스의 (W)\'쇠약\'이 빠진 것을 확인한 뒤 (W)\'방호의 도약\'으로 거리를 좁혀 딜교환을 시작하세요. (E)\'방패 돌격\'을 사용해 나서스의 공격을 방어하며 (Q)\'혜성의 창\'을 활용해 짧게 딜교환을 하고 빠르게 빠지세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 무리한 싸움은 피하는 게 좋아요. (R)\'거대 유성\'으로 먼저 진입해 폭발적인 피해를 입히거나, 라인을 밀어 정글러의 개입을 유도하세요.', item: '갈라진 하늘을 통해 전투 지속력을 높이는 것이 좋아요. 신발은 (Q)\'흡수의 일격\'의 물리 피해를 줄여주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 초반 압박을 강화하고 나서스의 체력 회복을 억제하여 킬각을 잡기 쉬워요.' },
    '녹턴': { lv1: '1~2레벨 구간에서는 녹턴의 (P)\'그림자 칼날\' 패시브를 통한 체력 회복을 경계하며 거리를 유지하세요. (Q)\'혜성의 창\'을 활용해 미니언과 함께 견제하며 녹턴이 (Q)\'황혼의 인도자\'로 빠르게 접근하지 못하도록 조심해야 해요.', lv3: '스킬이 모인 뒤에는 녹턴의 (W)\'어둠의 장막\'이 빠진 것을 확인하고 (W)\'방호의 도약\'으로 진입하는 것이 좋아요. (Q)\'혜성의 창\'을 먼저 던져서 상대의 보호막을 빼거나 (W)\'방호의 도약\'으로 기절을 맞히는 구도를 만드세요.', lv6: '녹턴이 (R)\'피해망상\'으로 시야를 차단하고 날아오면 그 방향으로 (E)\'방패 돌격\'을 들어 피해를 막아내세요. 녹턴의 궁극기가 빠진 뒤 (R)\'거대 유성\'으로 진입해 원하는 타이밍에 교전을 시작하는 것이 중요해요.', item: '판금 장화와 갈라진 하늘을 추천해요. 녹턴의 기본 공격 피해를 줄이면서 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화예요. 녹턴을 압박하여 킬을 따내거나 도망가는 적을 마무리하기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓이면 평타가 매우 아프니 1~2레벨에 무리하게 붙지 마세요. (Q)\'학살\'은 도끼날에 맞을수록 회복이 커지니 도끼날 범위 밖에서 (Q)\'혜성의 창\'으로 짧게 견제하며 거리를 조절하세요.', lv3: '(E)\'포획\'은 끌어당기며 공중으로 띄우니 맞기 전에 (W)\'방호의 도약\'으로 먼저 기절시키세요. 기절시킨 뒤 (Q)\'혜성의 창\'으로 몰아치고 빠르게 빠져나와야 해요. (W)\'마비의 일격\'에 걸리면 둔화되니 평타를 오래 주고받지 마세요.', lv6: '(P)\'과다출혈\' 중첩이 높을 때 다리우스의 (R)\'녹서스의 단두대\'는 매우 치명적이니 싸움을 피하세요. (R)\'거대 유성\'을 사용해 진입하며 적에게 둔화를 걸고 (W)\'방호의 도약\'으로 기절을 시키며 킬각을 보세요. 정글러가 근처에 있다면 다리우스가 (E)\'포획\'을 쓰기 전에 (W)\'방호의 도약\'으로 멈춰 세우고 함께 마무리하세요.', item: '다리우스의 물리 피해를 줄이기 위해 판금 장화를 구매하세요. 첫 코어 아이템으로는 공격력과 스킬 가속을 제공하는 삼위일체를 추천해요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당겨 들어올 때 탈진을 사용하면 피해량과 이동 속도를 줄여 위기를 넘길 수 있어요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'로 멀리서 견제하지만 첫 번째로 맞은 적에게만 피해를 입히니 미니언 뒤에 서서 피해를 최소화하세요. 1~2레벨에는 무리하게 진입하기보다 (Q)\'혜성의 창\'을 던져 라이즈의 체력을 갉아먹으며 거리를 조절하세요. 라이즈가 막타를 치러 오는 순간을 노려 평타 딜교환을 시도하세요.', lv3: '(E)\'주문 전이\' 표식이 남았을 때 (W)\'룬 감옥\'을 맞으면 속박되니, 표식이 붙었을 때 라이즈의 정면에서 너무 오래 머물지 마세요. 라이즈가 스킬을 사용하면 (E)\'방패 돌격\'으로 피해를 무효화하며 진입해 (W)\'방호의 도약\'으로 기절시킨 뒤 빠르게 딜교환을 끝내세요. (W)\'룬 감옥\'이 빠진 시점에는 라이즈가 나를 둔화시키거나 속박할 수단이 없으니 적극적으로 압박하세요.', lv6: '(R)\'거대 유성\'으로 진입해 라이즈를 둔화시키고 (W)\'방호의 도약\' 연계로 킬각을 잡으세요. 라이즈가 (R)\'공간 왜곡\'으로 차원문을 열어 빠져나갈 수 있으니, 차원문이 열리면 무리하게 쫓지 말고 라인을 밀어 포탑 피해를 입히세요. 상대 정글러의 위치가 확인되지 않았다면 라인을 너무 깊게 밀지 말고 적절히 유지하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 전투 중 체력을 회복하며 유지력을 높이세요. 신발은 헤르메스의 발걸음을 신어 마법 저항력을 얻고 제압과 에어본을 제외한 (W)\'룬 감옥\'의 속박 같은 군중 제어 지속시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 라이즈의 낮은 체력을 빠르게 깎아 확실하게 처치하기 위해 점화의 추가 피해가 필요해요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 켜고 근접한 적에게 강한 마법 피해를 입혀요. (Q)\'화염방사기\'가 닿는 원뿔 범위에 오래 서 있지 말고 (Q)\'혜성의 창\'을 짧게 찌르고 빠지세요. 럼블이 과열되어 스킬을 사용하지 못하는 틈을 타서 평타로 견제하며 경험치를 챙기세요.', lv3: '(E)\'전기 작살\'에 맞으면 둔화되고 마법 저항력이 깎이니 최대한 피하며 싸우세요. 럼블이 (Q)\'화염방사기\'를 쓰면 (E)\'방패 돌격\'으로 피해를 완전히 무시하고 진입하세요. (W)\'고철 방패\'가 사라진 시점에 (W)\'방호의 도약\'으로 기절시키고 강화된 평타를 넣어 짧은 딜교환을 마치세요.', lv6: '(R)\'이퀄라이저 미사일\'의 화염 벽 위에 있으면 지속 피해와 둔화가 심하니 즉시 범위를 벗어나세요. (R)\'거대 유성\'으로 진입한 뒤 럼블이 (W)\'고철 방패\'를 쓰면 (E)\'방패 돌격\'으로 시간을 끌며 아군 정글러의 합류를 기다리세요. 럼블이 과열 상태가 되어 스킬을 못 쓰는 타이밍에 (W)\'방호의 도약\'으로 들어가 킬각을 잡으세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 챙기고 강력한 한 방 피해를 입히세요. 신발은 (E)\'전기 작살\'과 (R)\'이퀄라이저 미사일\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티더라도 점화의 고정 피해를 더해 확실하게 마무리하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반에 강한 모습을 보여요. 1~2레벨에는 레넥톤의 분노가 쌓이지 않게 거리를 조절하며 (Q)\'혜성의 창\'으로 견제하세요. (W)\'무자비한 포식자\'의 기절에 걸리지 않도록 주의하며 라인을 관리해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 들어오면 (E)\'방패 돌격\'을 사용해 피해를 막아내세요. 레넥톤이 (W)\'무자비한 포식자\'를 먼저 사용했다면 (W)\'방호의 도약\'으로 들어가서 딜교환을 해요. 분노가 높은 상태에서 기절을 맞는 것은 위험하니 조심하세요.', lv6: '레넥톤이 (R)\'강신\'을 사용하면 체력이 늘어나고 강력해지니 정면 싸움은 피하세요. (R)\'강신\'이 켜져 있는 동안에는 (R)\'거대 유성\'을 아껴 두었다가 아군 정글러와 함께 싸울 때 진입용으로 쓰세요. 레넥톤의 궁극기 지속시간이 끝난 뒤에 (W)\'방호의 도약\'으로 승부를 보는 것이 좋아요.', item: '삼위일체를 첫 코어로 가서 전투력을 높이세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'양떼 도륙\'의 체력 회복 효과를 감소시킬 수 있어요.' },
    '렝가': { lv1: '1~2레벨 구간에는 렝가가 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 갑작스럽게 도약하는 것을 경계하세요. (Q)\'혜성의 창\'을 사용하여 거리를 유지하며 미니언과 함께 적을 견제해요. 무리하게 맞붙기보다 안전하게 파밍하며 다음 단계를 준비하세요.', lv3: '3레벨 이후에는 렝가가 (E)\'올가미 투척\'으로 둔화를 걸려고 할 때 (E)\'방패 돌격\'을 사용해 피해를 막아내세요. 렝가의 (W)\'전투의 포효\'를 통한 회복을 방해하기 위해 (W)\'방호의 도약\'으로 기절을 시키며 딜교환을 해요. 적의 야성 중첩이 쌓이지 않도록 주의하며 스킬을 사용하세요.', lv6: '6레벨 이후에는 렝가가 (R)\'사냥의 전율\'을 사용하여 위장 상태로 접근하면 (E)\'방패 돌격\'으로 공격을 흘려야 해요. (R)\'거대 유성\'을 사용해 적절한 위치에 떨어지며 전투를 주도하거나 도망치세요. 라인을 빠르게 밀어 넣고 정글러의 위치를 확인하며 움직여요.', item: '판금 장화와 갈라진 하늘을 구매하세요. 렝가의 기본 공격 피해를 줄이고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화. 렝가의 순간적인 진입에 대응하고 체력 회복 효과를 줄이기 위해서예요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용해 (P)\'룬 검\'을 충전하며 압박하려 해요. (Q)\'혜성의 창\'을 사용해 리븐의 접근을 견제하고 리븐이 돌진할 때는 거리를 조절하세요. (P)\'필멸자의 의지\'가 활성화될 때까지 차분하게 파밍하며 기다려요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 시도하기 전에 (W)\'방호의 도약\'으로 먼저 기절시키는 구도를 만드세요. 리븐이 (E)\'용맹\'으로 보호막을 얻고 들어올 때는 (W)\'방호의 도약\'을 아끼며 (Q)\'부러진 날개\'가 빠진 뒤에 교환해요. (E)\'방패 돌격\'은 정면 피해를 막아주니 리븐이 연속으로 돌진해 올 때 타이밍을 맞춰 사용하세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 공격 사거리와 피해량이 늘어나니 주의하세요. 리븐이 스킬 연계를 시작할 때 (E)\'방패 돌격\'으로 공격을 막아내고 (R)\'거대 유성\'으로 추격하거나 합류하세요. 리븐의 체력이 낮을 때 (W)\'방호의 도약\'과 (Q)\'혜성의 창\'을 연계해 킬을 노려요.', item: '리븐의 물리 피해를 줄이기 위해 판금 장화를 먼저 올려요. 첫 코어 아이템은 체력과 공격력을 모두 제공하는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮아졌을 때 점화로 마무리하며 킬을 가져오세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 멀리서 둔화를 걸며 견제하니 거리를 조절해야 해요. 1~2레벨에는 판테온의 (Q)\'혜성의 창\'이 강력하니 리산드라가 스킬을 쓰기 전에 먼저 접근해 압박하세요. 미니언을 사이에 두어도 (Q)\'얼음 파편\'은 꿰뚫고 지나가니 주의해야 해요.', lv3: '리산드라의 (W)\'서릿발\' 피해는 (E)\'방패 돌격\'으로 막을 수 있지만 속박은 그대로 걸리니, 속박 중에도 쓸 수 있는 (Q)\'혜성의 창\'으로 맞대응하세요. 리산드라가 (E)\'얼음갈퀴 길\'로 거리를 벌리려 하면 (W)\'방호의 도약\'을 사용해 바로 따라붙어야 해요. (W)\'서릿발\'을 먼저 빼게 유도하면 (Q)\'혜성의 창\'과 (W)\'방호의 도약\'으로 딜교환을 할 수 있어요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용해 무적 상태가 되면 딜을 낭비하지 말고 기다리세요. (R)\'얼음 무덤\'은 적에게 쓰면 기절시키는 대상 지정 스킬이라 걸어서 피할 수 없고 기절 중에는 스킬을 쓸 수 없으니, 리산드라의 궁극기가 빠진 것을 확인하고 싸우세요. (R)\'거대 유성\'을 활용해 멀리 있는 리산드라를 추격하거나 합류전에 참여하세요.', item: '헤르메스의 발걸음을 먼저 올려 리산드라의 군중 제어 지속 시간을 줄이세요. 첫 코어 아이템으로는 체력과 공격력을 모두 제공하는 갈라진 하늘을 추천해요.', spell: '점멸과 정화를 추천해요. 리산드라의 (W)\'서릿발\' 속박이나 (R)\'얼음 무덤\' 기절을 정화로 빠르게 풀고 다시 싸울 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'을 활용해 평타로 강하게 압박할 수 있어요. 1~2레벨에는 (Q)\'혜성의 창\'으로 견제하며 거리를 조절하는 데 집중하세요. 마스터 이가 (Q)\'일격 필살\'을 사용해 진입하기 전에 미리 거리를 벌려두는 것이 좋아요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용하면 대상으로 지정할 수 없으니 스킬이 끝난 뒤에 (W)\'방호의 도약\'으로 기절시키세요. (W)\'명상\'으로 체력을 회복할 때는 무리하게 싸우지 말고 물러나세요. (Q)\'혜성의 창\'을 사용해 (P)\'2연속 공격\'이 쌓이기 전에 견제하세요.', lv6: '(R)\'거대 유성\'은 마스터 이가 (R)\'최후의 전사\'를 쓰지 않은 타이밍에 떨어뜨려야 둔화가 들어가요. 마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화가 통하지 않으니 (W)\'방호의 도약\' 기절로 대응해야 해요. 마스터 이가 킬을 먹어 스킬 재사용 대기시간이 줄어들지 않도록 조심하세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 점화로 억제해야 해요.' },
    '마오카이': { lv1: '마오카이는 (P)\'마법 흡수\'로 체력을 회복하며 (Q)\'덤불 주먹\'으로 밀어내려 해요. (Q)\'혜성의 창\'을 던져 미리 견제하고, (Q)\'덤불 주먹\'에 밀려나지 않게 거리 조절을 하며 막타를 챙기세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약할 때는 대상으로 지정할 수 없으니, 속박이 끝난 뒤 (W)\'방호의 도약\'으로 진입하세요. (E)\'방패 돌격\'으로 마오카이의 (Q)\'덤불 주먹\' 피해를 무시하며 딜교환을 이어가세요. (E)\'묘목 던지기\'가 깔린 수풀에는 들어가지 않도록 주의하세요.', lv6: '(R)\'대자연의 마수\' 벽이 다가올 때 옆으로 피해 속박을 피하세요. 마오카이의 군중 제어기가 빠진 타이밍에 (R)\'거대 유성\'으로 진입해 킬각을 보세요. 수풀에 던진 (E)\'묘목 던지기\'는 더 오래 남고 폭발도 커지니 수풀 근처를 지날 때 조심하며 라인을 관리하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 강력한 한 방 피해를 입히세요. 신발은 마법 저항력을 높이고 속박과 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 마오카이는 (Q)\'덤불 주먹\'과 (W)\'뒤틀린 전진\'으로 라인을 압박하니 순간이동으로 라인에 복귀해 손해를 줄이세요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄고 군중 제어에 면역이 되니 (Q)\'혜성의 창\'으로 먼저 피해를 입혀 이 효과를 풀어 주세요. (Q)\'공허의 부름\'의 침묵 투사체 위치를 파악해 피하면서 미니언과 함께 압박하세요. 1~2레벨에는 말자하의 체력이 낮으니 거리를 좁혀 계속 괴롭히는 것이 좋아요.', lv3: '(E)\'방패 돌격\'으로 말자하의 (E)\'재앙의 환상\'과 공허충 피해를 무시하며 진입하세요. (Q)\'공허의 부름\' 침묵이 빠진 것을 확인한 뒤 (W)\'방호의 도약\'으로 진입해 기절시키고 짧게 딜교환을 하세요. 침묵에 걸리면 스킬을 못 쓰니 진입 전에 침묵을 먼저 피하는 것이 중요해요.', lv6: '(R)\'거대 유성\'으로 진입해 둔화를 걸고 빠르게 킬각을 잡으세요. 다만 (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 상대 궁극기가 있을 때는 무리하게 들어가지 마세요. (E)\'방패 돌격\'으로 정면 피해를 막으며 버티다가 상대의 궁극기가 빠진 시점에 다시 공격하세요.', item: '갈라진 하늘로 체력과 공격력을 챙겨 딜교환을 편하게 하세요. 신발은 마법 저항력을 제공하고 (Q)\'공허의 부름\' 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 점화로 확실하게 마무리하는 것이 효율적이에요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하고 (Q)\'지진의 파편\'으로 이동 속도를 훔치며 견제해요. (Q)\'지진의 파편\'은 대상 지정 스킬이라 피할 수 없으니 맞으면서 (Q)\'혜성의 창\'으로 빠르게 방패를 깨뜨리세요. 방패가 사라진 뒤에 짧게 딜교환을 하고 뒤로 물러나며 체력을 관리하세요.', lv3: '(W)\'방호의 도약\'으로 진입해 기절시킨 뒤 (Q)\'혜성의 창\'을 맞히고 (E)\'방패 돌격\'으로 상대의 반격을 막으세요. 말파이트가 (E)\'지면 강타\'를 사용해 공격 속도를 낮추기 전에 빠르게 콤보를 넣는 것이 중요해요. (W)\'천둥소리\'가 켜진 상태의 평타는 피해가 크니 (E)\'방패 돌격\'의 무적 시간으로 적절히 씹어주세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 막을 수 없으며, 맞으면 공중에 떠서 아무것도 못 하니 주의하세요. 말파이트가 궁극기를 헛쳤을 때 (R)\'거대 유성\'으로 진입해 둔화를 걸고 강력하게 몰아붙이세요. 라인을 밀어 넣은 뒤 정글러가 올 때까지 거리 조절을 하며 (R)\'멈출 수 없는 힘\'의 사거리를 주지 마세요.', item: '방어력이 높은 말파이트를 상대하기 위해 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (Q)\'지진의 파편\'의 둔화와 (E)\'지면 강타\'의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 초반에 (W)\'방호의 도약\'과 점화를 함께 사용해 말파이트를 빠르게 처치하며 압박하세요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'로 대상을 맞히면 피해가 커지고 스킬을 반복해서 적중시키면 (P)\'암흑 탄생\' 오라가 켜져요. (Q)\'말살\'의 사거리가 더 길어 사거리 밖 견제는 어려우니 (Q)\'말살\'을 쓰는 타이밍에 옆으로 비켜서세요. (Q)\'혜성의 창\'은 (Q)\'말살\'이 빠진 뒤에 짧게 찌르고 초반에는 미니언을 챙기며 힘을 모으세요.', lv3: '(E)\'방패 돌격\'을 사용하여 모데카이저의 (Q)\'말살\'이나 (E)\'죽음의 손아귀\' 피해를 막아내며 딜교환을 시작하세요. (W)\'방호의 도약\'으로 진입해 기절시킨 뒤 (Q)\'혜성의 창\'으로 추가 피해를 입히고 바로 빠지는 것이 좋아요. 모데카이저가 (W)\'불멸\'로 보호막을 만들기 전에 빠르게 공격하고 물러나세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 탈출이 불가능하고 능력치를 뺏기게 되니 조심해야 해요. 모데카이저의 (E)\'죽음의 손아귀\'가 빠지면 라인을 밀어 넣고 (R)\'거대 유성\'으로 진입해 싸움을 걸면 좋아요. (E)\'방패 돌격\'을 아껴두었다가 모데카이저의 스킬을 막아내며 정글러와 함께 킬을 노리세요.', item: '헤르메스의 발걸음을 구매해 모데카이저의 마법 피해와 군중 제어 효과에 대비하세요. 갈라진 하늘을 첫 코어로 가면 체력과 공격력을 동시에 챙길 수 있어 전투에서 버티기 편해요.', spell: '점멸과 점화를 추천해요. 점화로 모데카이저의 (W)\'불멸\'을 통한 체력 회복 효과를 줄여 킬을 따기 쉽게 만드세요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력에 비례한 피해를 주고 둔화를 걸어요. 이 스킬은 처음 맞은 대상에게만 적중하니 미니언 뒤에 숨어서 피하고, 거리 조절을 하며 (Q)\'혜성의 창\'으로 견제하세요. 초반부터 무리하게 붙기보다 짧게 찌르는 방식으로 체력을 갉아먹으세요.', lv3: '문도 박사의 (P)\'가고 싶은 데로 간다\'는 처음 맞는 이동 불가 효과에 저항하니 패시브가 빠진 것을 확인한 뒤에 (W)\'방호의 도약\'으로 기절을 넣으세요. (E)\'방패 돌격\'은 (E)\'둔기에 의한 외상\'의 강한 타격을 정면에서 막는 데 쓰세요. (W)\'방호의 도약\' 뒤의 강화된 평타를 섞어 지속적으로 압박하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 엄청난 양의 체력을 회복하니, 궁극기를 쓰기 전에 (R)\'거대 유성\'으로 진입해 빠르게 피해를 누적시키세요. 회복이 시작되면 추격하기 어려우니 라인을 밀어넣고 정글러를 불러 함께 공격하는 것이 좋아요. (E)\'방패 돌격\'으로 정면 공격을 막으며 상대의 스킬 쿨타임을 기다리세요.', item: '몰락한 왕의 검을 첫 코어로 가서 최대 체력이 높은 문도 박사에게 효율적인 피해를 입히세요. 신발은 (Q)\'오염된 뼈톱\'과 (W)\'심장 전기 충격\'의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 (R)\'최대 투여량\'과 패시브의 체력 재생이 매우 강력하므로 점화의 치유 감소 효과가 필수적이에요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 충전해 긴 사거리에서 견제하니, 정면에서 맞지 않게 옆으로 움직이세요. 바루스가 화살을 쏘기 위해 멈추는 순간에 (Q)\'혜성의 창\'을 던져 거리를 좁히며 압박하세요. 첫 웨이브는 최대한 피해를 줄이며 경험치를 챙기세요.', lv3: '(E)\'방패 돌격\'으로 바루스의 (Q)\'꿰뚫는 화살\'이나 (E)\'퍼붓는 화살\' 피해를 무시하며 진입하세요. 바루스가 (W)\'역병 화살\' 중첩을 쌓기 전에 (W)\'방호의 도약\'으로 빠르게 진입해 기절시키고 공격하세요. 진입 전 (Q)\'혜성의 창\'을 먼저 맞혀 체력을 깎아두면 더 효과적이에요.', lv6: '(R)\'거대 유성\'으로 빠르게 진입해 바루스를 둔화시키고 킬각을 잡으세요. 진입 시 바루스의 (R)\'부패의 사슬\'에 속박되면 이동이 막히니, 최대한 사선에서 진입하세요. 속박된 상태에서도 평타는 가능하니 당황하지 말고 (E)\'방패 돌격\'으로 이어지는 콤보를 준비하세요.', item: '판금 장화는 바루스의 기본 공격 피해를 줄여줘서 버티기 좋아요. 갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 강력한 한 방 피해와 체력 회복을 챙기세요.', spell: '점멸과 점화를 추천해요. 점화로 바루스의 체력을 깎고 마무리 피해를 입혀 확실하게 처치하세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 (W)\'은화살\'의 고정 피해로 견제해요. 1~2레벨에는 무리하게 붙기보다 (Q)\'혜성의 창\'을 길게 눌러 던지며 체력을 깎으세요. 베인이 미니언을 치러 다가올 때만 짧게 딜교환을 하고 빠르게 빠지세요.', lv3: '베인의 (E)\'선고\'는 벽에 부딪히면 기절시키니 벽 근처에 서지 마세요. (E)\'방패 돌격\'으로 베인의 평타와 (W)\'은화살\' 피해를 무시하며 진입하고, (W)\'방호의 도약\'으로 기절시킨 뒤 빠르게 공격하세요. 베인이 (Q)\'구르기\'로 거리를 벌리기 전에 (Q)\'혜성의 창\'으로 마무리하세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\' 사용 시 투명해져서 공격하기 까다로워요. (R)\'거대 유성\'으로 먼저 둔화시킨 뒤, 베인이 투명 상태가 아닐 때 (W)\'방호의 도약\'으로 진입해 빠르게 잡으세요. 투명 상태일 때는 무리하게 쫓지 말고 (E)\'방패 돌격\'으로 시간을 버티세요.', item: '판금 장화는 베인의 기본 공격 피해를 줄여줘서 버티기 좋아요. 갈라진 하늘을 첫 코어로 가서 체력을 보충하고 첫 타격의 추가 피해와 회복으로 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. (W)\'방호의 도약\'과 함께 점멸로 진입하고, 체력이 낮은 베인을 점화로 확실히 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 달려들어 기절을 걸며 강하게 압박해요. (Q)\'혜성의 창\'을 활용해 짧게 찔러 견제하며 볼리베어의 (Q)\'번개 강타\' 사용을 유도하세요. 1~2레벨 구간에서는 무리하게 붙지 말고 거리를 유지하며 미니언을 챙겨요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남기고 다시 사용해 체력을 회복하기 전에 (E)\'방패 돌격\'으로 피해를 막아내세요. (W)\'방호의 도약\'으로 볼리베어를 기절시킨 뒤 (Q)\'혜성의 창\'으로 연속 딜교환을 시도해요. 볼리베어가 (E)\'천공 분열\'을 떨어뜨리면 번개가 내려치는 위치에서 벗어나 둔화를 피하세요.', lv6: '볼리베어는 (R)\'폭풍을 부르는 자\'를 사용해 포탑을 비활성화하며 다이브할 수 있으니 조심하세요. 볼리베어의 궁극기가 빠진 것을 확인한 뒤 (R)\'거대 유성\'으로 진입하여 전투를 시작해요. 라인을 빠르게 밀어 넣고 (R)\'거대 유성\'을 이용해 다른 라인에 합류하는 플레이를 하세요.', item: '삼위일체를 첫 코어로 올려 공격력과 스킬 가속을 챙기세요. 신발은 볼리베어의 마법 피해와 군중 제어 효과를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어의 (W)\'광란의 상처\'를 통한 체력 회복을 억제하기 위해 점화를 사용하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'을 사용해 체력을 회복하며 견제하니 거리 조절에 유의하세요. (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 주의해야 해요. 초반에 판테온이 힘을 발휘하는 구간이므로 (Q)\'혜성의 창\'으로 꾸준히 압박하며 주도권을 가져오세요.', lv3: '블라디미르가 (W)\'피의 웅덩이\'를 사용하여 대상 지정이 불가능해지면 스킬을 아끼며 기다리세요. (W)\'방호의 도약\'으로 기절을 맞힌 뒤 (Q)\'혜성의 창\'을 사용하여 강력한 교전을 시도하세요. (E)\'선혈의 파도\'는 미니언 뒤에 숨어 피해를 줄일 수 있으니 위치 선정이 중요해요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용하면 받는 피해가 증가하니 무리하게 싸우지 말고 거리를 두세요. (R)\'거대 유성\'으로 적의 움직임을 둔화시킨 뒤 (W)\'방호의 도약\'과 (Q)\'혜성의 창\'을 연계해 킬각을 노리세요. 블라디미르가 성장할수록 강해지니 라인을 밀어 넣고 정글러를 불러 적극적으로 교전하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 피해를 줄이기 위해 헤르메스의 발걸음을 사고 전투 지속력을 위해 갈라진 하늘을 가요.', spell: '점멸과 점화. 블라디미르의 (Q)\'수혈\' 회복량을 억제해야 킬을 낼 수 있어요.' },
    '뽀삐': { lv1: '뽀삐는 (Q)\'망치 강타\'의 지대로 인해 움직임이 둔화될 수 있으니 주의하세요. (Q)\'혜성의 창\'으로 견제하며 뽀삐가 (P)\'강철의 외교관\'으로 방패를 주우러 올 때 거리를 조절하세요. 벽 근처에서 싸우면 (E)\'용감한 돌진\'에 기절할 수 있으니 라인 중앙을 유지하세요.', lv3: '뽀삐의 (W)\'굳건한 태세\'는 (W)\'방호의 도약\'과 같은 돌진기를 막고 이동 스킬 사용을 막아요. 뽀삐가 (W)\'굳건한 태세\'를 사용했을 때는 무리하게 진입하지 말고 스킬이 빠지기를 기다리세요. (E)\'방패 돌격\'을 사용해 뽀삐의 (Q)\'망치 강타\' 피해를 막으며 딜교환을 시도하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'을 사용하면 멀리 날아가니 충전하는 모습을 보이면 즉시 거리를 벌리세요. (R)\'거대 유성\'을 사용하여 뽀삐의 체력을 깎고 (P)\'필멸자의 의지\'로 강화된 (Q)\'혜성의 창\'을 맞춰 킬각을 잡으세요. 뽀삐의 (E)\'용감한 돌진\'으로 벽에 부딪히지 않도록 라인 관리와 위치 선정이 중요해요.', item: '갈라진 하늘을 첫 코어로 선택하여 전투 지속력을 높이세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 빠르게 깎아 킬각을 잡기 쉬워져요.' },
    '사이온': { lv1: '사이온이 (E)\'학살자의 포효\'를 사용해 미니언을 맞히면 뒤에 있는 적까지 둔화와 방어력 감소가 적용되니 미니언과 일직선이 되지 않도록 주의하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 동작이 보이면 (Q)\'혜성의 창\'으로 견제하며 거리를 유지하세요.', lv3: '사이온의 (W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 (W)\'방호의 도약\'으로 진입해도 피해가 흡수되니 보호막이 사라진 뒤에 (Q)\'혜성의 창\'을 사용하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 동안에는 (W)\'방호의 도약\'을 아껴두었다가 타이밍을 봐서 진입하세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 옆으로 비켜서서 충돌을 피하고 (R)\'거대 유성\'으로 거리를 조절하세요. 사이온은 처치된 후에도 (P)\'영광스러운 죽음\'으로 공격하며 버티니 무리한 추격보다는 라인을 관리하는 것이 좋아요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 확보하세요. 신발은 사이온의 기본 공격 피해를 줄여주는 판금 장화를 추천해요. 판금 장화는 (Q)\'대량 학살 강타\' 같은 스킬 피해는 줄이지 못해요.', spell: '점멸과 점화를 추천해요. 사이온과의 근접 교전에서 (W)\'방호의 도약\'으로 진입할 때 점화를 사용하여 승부를 보세요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'로 견제하고 (P)\'페트리사이트 폭발\' 평타를 섞어 공격해요. (Q)\'사슬 후려치기\'가 교차하며 터지는 지점을 피해 서면서 (Q)\'혜성의 창\'으로 맞딜을 하세요. 1~2레벨에는 무리하게 붙기보다 짧은 딜교환으로 체력을 깎아 놓으세요.', lv3: '(W)\'방호의 도약\'으로 진입한 뒤 (Q)\'혜성의 창\'과 (E)\'방패 돌격\'으로 빠르게 딜교환을 하세요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하려 할 때 (E)\'방패 돌격\'을 사용해 피해를 막고 반격하세요. (E)\'도주 / 억압\'의 재사용 돌진 사슬에 맞지 않도록 옆으로 움직이는 것이 중요해요.', lv6: '(R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 이어지는 콤보로 킬각을 잡으세요. 사일러스는 (R)\'강탈\'로 내 (R)\'거대 유성\'을 훔쳐 쓸 수 있으니 체력을 관리하며 싸우세요. 정글러가 오면 사일러스가 (E)\'도주 / 억압\'으로 빠져나가기 전에 (W)\'방호의 도약\'으로 기절시켜 함께 마무리하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 보충하고 라이트실드 타격으로 피해를 입히세요. 신발은 마법 저항력과 강인함으로 사일러스의 마법 피해와 군중 제어 시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'국왕시해자\'의 체력 회복 효과를 감소시켜 킬각을 잡기 편하게 하세요.' },
    '세주아니': { lv1: '세주아니가 (Q)\'혹한의 맹습\'으로 돌진해 에어본을 시키려 하면 거리를 조절하며 피하세요. (Q)\'혜성의 창\'을 활용해 짧게 사용하여 미니언과 함께 견제하며 서리 중첩이 쌓이지 않도록 주의해야 해요. 1~2레벨 구간에는 무리한 진입보다 거리 유지를 하며 상대의 움직임을 관찰하는 것이 좋아요.', lv3: '세주아니가 (W)\'혹한의 서릿발\'로 둔화를 걸며 접근하면 (E)\'방패 돌격\'을 사용해 피해를 버텨내세요. 상대의 (Q)\'혹한의 맹습\'이 빠진 타이밍에 (W)\'방호의 도약\'을 맞춰 기절을 시키고 딜교환을 시도해요. (Q)\'혜성의 창\'을 길게 던져 체력이 낮은 상태에서 추가 피해를 주는 것도 좋아요.', lv6: '세주아니가 (R)\'빙하 감옥\'을 사용해 기절을 시키면 대응하기 어려우니 주의하세요. (R)\'거대 유성\'으로 먼저 진입하거나 아군과 함께 싸워 (E)\'만년 서리\'의 기절이 들어오기 전에 먼저 교전을 시작해요. 라인을 빠르게 밀고 (R)\'거대 유성\'을 사용해 다른 라인의 싸움에 빠르게 합류하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 세주아니의 다양한 군중 제어 효과에 대응하기 위해 헤르메스의 발걸음이 필요하고, 전투 지속력을 높이기 위해 갈라진 하늘을 선택해요.', spell: '점멸과 점화. 세주아니의 체력을 낮춘 뒤 (W)\'방호의 도약\'으로 진입하여 점화로 확실하게 마무리하기 위해서예요. 적극적인 딜교환이 필요해요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 사용하여 이동 속도를 높이고 강력한 평타를 날리며 다가와요. (Q)\'혜성의 창\'으로 먼저 거리를 두며 견제하고 세트가 (P)\'투기장의 투지\'로 체력을 회복하기 전에 피해를 입히세요. 초반에는 무리하게 맞붙기보다 거리 조절에 집중하며 (Q)\'혜성의 창\'을 맞히는 데 주력해요.', lv3: '세트가 (W)\'강펀치\'를 사용하여 보호막을 얻고 고정 피해를 입히기 전에 (E)\'방패 돌격\'으로 피해를 막아내는 것이 중요해요. 세트의 (E)\'안면 강타\'에 끌려가지 않도록 위치를 선정하고 (W)\'방호의 도약\'으로 세트의 움직임을 끊으세요. (Q)\'혜성의 창\'과 (W)\'방호의 도약\'을 연계하여 세트의 스킬이 빠진 틈을 노려 딜교환을 해요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 제압한 뒤 바닥에 내리꽂으면 큰 피해를 입으니 주의해야 해요. (R)\'거대 유성\'으로 세트에게 둔화를 걸고 (E)\'방패 돌격\'을 활용해 세트의 반격을 버티며 싸우세요. 세트가 (W)\'강펀치\' 보호막을 쓰기 전에 (R)\'거대 유성\'으로 진입하여 압박하는 것이 좋아요.', item: '판금 장화로 세트의 기본 공격 피해를 줄이고 갈라진 하늘을 첫 코어로 선택해요. 이 아이템은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 세트가 (P)\'투기장의 투지\'로 체력을 회복하는 것을 점화로 억제하며 킬을 노려보세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 피해를 입히며 (P)\'기 보호막\'을 얻으니 무리한 교환은 피하세요. 쉔이 (Q)\'황혼 강습\'을 사용해 보호막을 쓴 직후에 (Q)\'혜성의 창\'을 던져 견제하며 거리를 유지하세요. 1~2레벨에는 쉔의 기의 검 사거리 안으로 들어가지 않도록 주의하며 미니언을 챙기세요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼치면 기본 공격이 막히니 (W)\'방호의 도약\'으로 도약한 뒤 (Q)\'혜성의 창\'을 맞춰 딜을 넣으세요. 쉔이 (E)\'그림자 돌진\'으로 들어올 때 (E)\'방패 돌격\'을 사용해 피해를 줄이고, 도발이 끝난 뒤 (W)\'방호의 도약\'으로 기절을 시키세요. 쉔의 (P)\'기 보호막\'이 사라지는 타이밍을 노려 (P)\'필멸자의 의지\'가 활성화된 스킬을 쏟아부으세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인에 합류하면 빠르게 라인을 밀어 포탑 압박을 시작하세요. 쉔의 궁극기가 빠진 상태라면 (R)\'거대 유성\'으로 진입해 (W)\'방호의 도약\'과 (Q)\'혜성의 창\'으로 킬각을 잡으세요. 쉔이 (E)\'그림자 돌진\'을 사용하며 들어올 때 (E)\'방패 돌격\'으로 적절히 대응하며 딜 교환을 이어가세요.', item: '삼위일체를 첫 코어로 올려 공격력과 스킬 가속을 확보하세요. 신발은 쉔의 기본 공격 피해를 줄이기 위해 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 교환 마지막에 체력을 더 깎아 마무리하세요.' },
    '쉬바나': { lv1: '1~2레벨 구간에는 쉬바나가 (Q)\'잉걸불 일격\'으로 다가오는 것을 조심하며 거리를 유지하세요. (Q)\'혜성의 창\'을 활용해 미니언과 함께 쉬바나의 체력을 깎으며 압박해요. 초반에는 무리하게 싸우기보다 미니언을 챙기는 데 집중하세요.', lv3: '쉬바나가 (W)\'지옥불 방패\'로 보호막을 얻었다면 무리하게 들어가지 마세요. (W)\'방호의 도약\'으로 쉬바나를 기절시킨 뒤 (Q)\'혜성의 창\'을 맞춰서 딜교환을 해요. 쉬바나의 (E)\'용암 분출\'이 날아올 때 (E)\'방패 돌격\'으로 피해를 막아내는 것이 좋아요.', lv6: '쉬바나가 (R)\'용의 강림\'을 사용하여 변신하며 달려들 때 (E)\'방패 돌격\'을 사용하여 공격을 막아내세요. (R)\'거대 유성\'을 사용해 쉬바나의 움직임을 둔화시키고 추격하거나 도망칠 준비를 해요. 정글러를 불러서 쉬바나가 용 형상을 유지하기 전에 빠르게 처치하세요.', item: '헤르메스의 발걸음과 삼위일체를 선택하세요. 쉬바나의 마법 피해를 견디며 전투 효율을 높이기 위해서예요.', spell: '점멸과 점화예요. 점화를 사용해 쉬바나의 체력 회복 효과를 줄이고 확실하게 킬을 노려요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'를 통해 체력을 회복해요. 무리하게 접근하기보다 (Q)\'혜성의 창\'을 길게 눌러 던지며 거리를 조절하세요. (Q)\'죽음의 손길\'은 번개가 여러 번 맞을수록 피해가 커지니 스웨인 정면 가까이에 오래 서 있지 마세요.', lv3: '스웨인의 (E)\'속박명령\'에 속박되면 이동은 막히지만 스킬은 쓸 수 있으니, 파동이 돌아오는 경로에서 비켜서세요. (E)\'속박명령\'이 빠진 것을 확인한 뒤 (W)\'방호의 도약\'으로 진입해 빠르게 딜교환을 하세요. (W)\'제국의 눈\'에 맞으면 둔화되니 무리하게 쫓아가기보다 스킬 쿨타임을 계산하며 접근하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변 체력을 흡수하니 너무 오래 붙어 있지 마세요. (R)\'거대 유성\'으로 빠르게 진입해 폭발적인 피해를 주고 (E)\'방패 돌격\'으로 흡수 피해를 최소화하며 빠져나오세요. 라인을 밀어 넣고 정글러를 호출하면 스웨인이 (R)\'악의 승천\'으로 버텨도 쉽게 처치할 수 있어요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 챙기고 생명선 보호막으로 생존력을 높이세요. 신발은 (E)\'속박명령\'의 속박 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'악의 승천\'과 (P)\'굶주린 새떼\'의 강력한 회복력을 점화의 치유 감소 효과로 억제해야 해요.' },
    '스카너': { lv1: '1~2레벨 구간에서는 (Q)\'혜성의 창\'을 활용해 멀리서 스카너의 체력을 깎아두는 것이 좋아요. 스카너가 (Q)\'부서진 대지/지반 돌출\'로 바위를 던지며 견제할 때는 거리 조절을 잘하며 피해를 최소화하세요. 초반에는 스카너의 공격이 위협적일 수 있으니 무리하게 들어가지 말고 미니언을 챙기며 차분히 대응해요.', lv3: '3레벨 이후에는 (W)\'방호의 도약\'을 사용하여 스카너에게 진입한 뒤 (Q)\'혜성의 창\'으로 딜교환을 해요. 스카너가 (E)\'이쉬탈의 격돌\'로 벽까지 끌고 가려 한다면 미리 거리를 두거나 스킬을 아끼는 것이 중요해요. 스카너의 (W)\'대지의 수호자\'가 사용될 때 (E)\'방패 돌격\'으로 피해를 막아내며 맞대응하는 구도를 만들어보세요.', lv6: '6레벨 이후 스카너가 (R)\'꿰뚫기\'를 사용해 제압을 시도하면 매우 위험하니 주의해야 해요. (R)\'거대 유성\'을 사용하여 멀리서 먼저 떨어져 둔화를 걸고 교전 주도권을 가져오세요. 라인을 밀어 넣은 뒤 정글러의 도움을 받아 스카너가 (E)\'이쉬탈의 격돌\'을 쓰기 까다로운 위치에서 압박해요.', item: '첫 코어 아이템으로는 전투 지속력을 높여주는 삼위일체를 추천해요. 신발은 스카너의 둔화 효과를 줄여주는 헤르메스의 발걸음을 선택하는 것이 좋아요.', spell: '점멸과 점화. 점화를 사용하여 스카너의 체력이 낮을 때 확실하게 킬을 노려보세요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'로 지속 피해를 주고 (P)\'독성 급류\'로 빠르게 움직여요. 무리하게 쫓아가다 독구름에 닿으면 체력이 깎이니 적당한 거리를 유지하세요. 신지드가 미니언을 치러 다가올 때 (Q)\'혜성의 창\'을 던져 견제하며 경험치만 챙기세요.', lv3: '(W)\'초강력 접착제\' 위에 있을 때는 (W)\'방호의 도약\'을 사용할 수 없으니 바닥을 잘 확인하세요. (E)\'던져넘기기\'를 쓰러 다가올 때 (E)\'방패 돌격\'으로 정면 피해를 무시하고 진입해 공격하세요. (W)\'방호의 도약\'으로 기절시킨 후 빠르게 딜교환을 하고 신지드가 (Q)\'맹독의 자취\'를 남기며 도망가면 쫓지 마세요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 방어력과 체력 재생력이 올라가니 정면에서 오래 싸우지 마세요. (W)\'초강력 접착제\'가 빠진 것을 확인하고 (R)\'거대 유성\'으로 진입해 둔화를 걸며 딜교환을 하세요. 라인을 밀어 넣고 정글러와 함께 신지드를 몰아넣어 킬각을 잡는 것이 효율적이에요.', item: '갈라진 하늘을 가서 체력과 공격력으로 지속 교전 능력을 높이세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'광기의 물약\'의 재생력을 억제하고 체력이 낮은 신지드를 마무리하기 좋아요.' },
    '신짜오': { lv1: '(Q)\'혜성의 창\'을 짧게 눌러 견제하며 신 짜오가 (Q)\'삼조격\'의 세 번째 평타로 공중으로 띄우지 못하게 거리를 조절하세요. 신 짜오가 (W)\'풍전참뢰\'를 사용할 때 (E)\'방패 돌격\'을 사용하여 피해를 받아내며 체력을 관리해요.', lv3: '신 짜오가 (E)\'무쌍돌격\'으로 진입하면 (W)\'방호의 도약\'으로 기절을 시키고 (E)\'방패 돌격\'을 사용하여 들어오는 피해를 막으세요. 신 짜오의 (Q)\'삼조격\' 쿨타임 동안 (Q)\'혜성의 창\'을 던져서 딜교환을 시도하는 것이 좋아요. (E)\'방패 돌격\'의 피해 면역 효과를 활용해 상대의 돌진기를 받아내며 싸워요.', lv6: '(R)\'거대 유성\'으로 진입하여 둔화를 걸고 전투를 시작하되 신 짜오가 (R)\'현월수호\'로 공격을 피하거나 밀쳐내지 않도록 주의하세요. (R)\'현월수호\'를 쓴 신 짜오는 창이 닿는 거리 밖에서 들어오는 공격에 피해를 입지 않으니, 밀려났다면 (Q)\'혜성의 창\'을 던지지 말고 다시 붙어서 공격하세요. 정글러를 불러서 신 짜오의 (R)\'현월수호\'가 빠진 타이밍에 함께 압박하세요.', item: '판금 장화와 갈라진 하늘을 선택하세요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 갈라진 하늘은 타격 시 체력을 회복하고 피해를 입혀요.', spell: '점멸과 점화를 사용하세요. 신 짜오의 (P)\'결심\'으로 인한 체력 회복을 억제하고 부족한 마무리 피해를 입히기 위해 필요해요.' },
    '아이번': { lv1: '아이번이 (Q)\'덩굴뿌리\'를 사용하여 속박을 시도하기 전에 거리를 조절하며 (Q)\'혜성의 창\'으로 압박하세요. (W)\'수풀 가꾸기\'로 생성된 수풀을 통해 시야를 잃지 않도록 주의하며 미니언을 관리하세요. 1~2레벨 구간에는 적극적으로 공격하여 상대가 편하게 성장하지 못하도록 하세요.', lv3: '아이번의 (Q)\'덩굴뿌리\'는 처음 맞은 적을 속박하니 미니언 뒤에 서서 피하고, 빗나갔을 때 (W)\'방호의 도약\'으로 진입하세요. 상대의 (E)\'보호의 씨앗\'이 빠진 타이밍에 (Q)\'혜성의 창\'과 함께 딜교환을 시도하는 것이 좋아요. (E)\'방패 돌격\'을 통해 아이번의 공격을 막아내는 타이밍을 잘 잡으세요.', lv6: '(R)\'거대 유성\'을 활용해 멀리서 진입하거나 정글러의 개입을 유도하여 교전을 만드세요. (R)\'데이지!\'가 소환되면 데이지의 공격과 (Q)\'덩굴뿌리\'를 조심하며 (E)\'방패 돌격\'으로 피해를 막으세요. 데이지의 공격에 의한 공중으로 띄우기 효과를 경계하며 싸워야 해요.', item: '헤르메스의 발걸음과 삼위일체를 추천해요. 아이번의 다양한 군중 제어 효과에 대응하기 위해 헤르메스의 발걸음을 가고, 강력한 공격력을 위해 삼위일체를 선택해요.', spell: '점멸과 점화. 점화를 사용하여 추가 피해를 입히며 킬을 노리는 것이 좋아요. 교전 중에 변수를 만들기 위해 점멸을 활용하세요.' },
    '아지르': { lv1: '1~2레벨에는 아지르가 (W)\'일어나라!\'와 (Q)\'사막의 맹습\'으로 계속 견제해요. 두 스킬 모두 일직선상의 적을 통과하며 맞히니 미니언 뒤에 숨기보다 옆으로 비켜서세요. 무리하게 진입하기보다 (Q)\'혜성의 창\'을 길게 눌러 던지며 체력을 관리하세요.', lv3: '(W)\'방호의 도약\'으로 진입하기 전 (E)\'방패 돌격\'을 사용해 (W)\'일어나라!\'의 피해를 무시하세요. 아지르가 (E)\'신기루\'로 도망가기 전에 기절을 맞히는 것이 중요해요. (P)\'필멸자의 의지\'가 강화된 상태에서 딜교환을 시도하세요.', lv6: '(R)\'거대 유성\'으로 진입할 때 아지르가 (R)\'황제의 진영\'으로 밀어내지 못하도록 주의하세요. 상대의 궁극기가 빠진 타이밍에 (W)\'방호의 도약\'과 연계해 킬각을 잡아요. 정글러를 불러 함께 공격하며 (E)\'방패 돌격\'으로 아지르의 반격을 받아내세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높여 (W)\'일어나라!\'의 피해를 줄이고 생명선 보호막으로 생존력을 높여요.', spell: '점멸과 점화를 추천해요. 아지르의 체력이 낮을 때 확실하게 마무리하고 압박하기 좋아요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 견제하며 (P)\'암살자의 표식\' 원을 그리려 할 때 적절한 거리를 유지하세요. (Q)\'혜성의 창\'을 길게 눌러 던지며 맞딜을 하기보다 상대의 기력이 빠질 때까지 기다리는 것이 좋아요. 첫 웨이브에서는 무리하게 진입하지 말고 체력 관리에 집중하세요.', lv3: '아칼리가 (W)\'황혼의 장막\'을 쓰면 대상 지정이 안 되니 (W)\'방호의 도약\' 사용 시점을 주의하세요. (E)\'표창곡예\'의 투사체를 (E)\'방패 돌격\'으로 막아내며 진입하면 피해를 크게 줄일 수 있어요. 연막이 사라진 직후 (W)\'방호의 도약\'으로 기절시키고 빠르게 딜교환을 마치고 빠지세요.', lv6: '(R)\'거대 유성\'은 범위 피해라 (W)\'황혼의 장막\' 안에 숨은 아칼리에게도 적중하니 이를 활용해 킬각을 잡으세요. 다만 (R)\'무결처형\'의 두 번째 돌진은 잃은 체력에 비례한 피해가 크니 체력이 낮을 때는 조심해야 해요. 라인을 밀어 넣고 정글러와 함께 (W)\'방호의 도약\' 연계로 빠르게 잡아내세요.', item: '맬모셔스의 아귀와 헤르메스의 발걸음을 추천해요. 아칼리의 강력한 마법 폭발 피해를 마법 저항력과 생명선 보호막으로 버텨낼 수 있어요.', spell: '점멸과 점화를 추천해요. 아칼리와의 짧은 교전에서 확실한 마무리 피해를 입히기 위해서예요.' },
    '아크샨': { lv1: '(Q)\'복수의 부메랑\' 사거리 때문에 초반에 거리를 유지하며 견제를 받아내야 해요. (Q)\'혜성의 창\'을 활용해 미니언과 함께 적을 압박하며 성장에 집중하세요. 상대의 기본 공격에 노출되지 않도록 주의하며 라인을 관리해요.', lv3: '(E)\'방패 돌격\'을 사용하여 (Q)\'복수의 부메랑\'의 피해를 막으면서 진입하는 것이 중요해요. (W)\'방호의 도약\'으로 적을 기절시킨 뒤 강화된 (Q)\'혜성의 창\'을 맞히며 딜교환을 해요. 상대가 (E)\'영웅의 비상\'으로 도망가지 못하게 스킬을 연계하세요.', lv6: '아크샨이 (E)\'영웅의 비상\'을 쓴 직후 (R)\'거대 유성\'으로 떨어져 둔화를 걸고 (W)\'방호의 도약\'으로 이어가 킬을 노리세요. 상대가 (R)\'인과응보\'로 체력이 낮은 나를 마무리하지 못하게 체력 관리에 신경 써야 해요. (R)\'인과응보\'는 처음 적중하는 챔피언이나 미니언에 맞으니 미니언 뒤로 몸을 숨겨 피해를 줄이세요.', item: '판금 장화와 갈라진 하늘을 선택해요. 상대의 기본 공격 피해를 줄이고 전투 지속력을 높여요.', spell: '점멸과 점화. 상대의 체력을 낮춰 (R)\'인과응보\'를 사용하기 전에 처치하거나 압박하기 위해 사용해요. 부족한 킬 결정력을 보완해줘요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\'을 세 번 휘두르는데 끝부분에 맞으면 공중으로 띄워지니 범위를 피해 서세요. (P)\'사신 태세\' 평타는 체력을 회복하니 평타 교환은 짧게 끝내세요. (Q)\'혜성의 창\'을 던져 적당한 거리를 유지하며 체력을 깎으세요.', lv3: '(W)\'지옥사슬\'에 맞으면 빠르게 범위를 벗어나 중앙으로 끌려가는 피해를 피하세요. 아트록스가 (Q)\'다르킨의 검\'을 내리칠 때 (E)\'방패 돌격\'을 사용해 피해를 무효화하고 진입하세요. 이후 (W)\'방호의 도약\'으로 기절시키고 빠르게 딜교환을 마친 뒤 빠지세요.', lv6: '(R)\'세계의 종결자\'를 켠 아트록스는 회복량과 공격력이 늘어나므로 정면 대결은 피하세요. 상대의 (Q)\'다르킨의 검\'이 모두 빠진 시점에 (R)\'거대 유성\'으로 진입해 폭발적인 피해를 입히세요. 정글러와 함께 싸울 때는 아트록스가 궁극기로 처치 관여를 하여 지속시간을 늘리지 않게 빠르게 처리하세요.', item: '체력 회복을 억제하는 처형인의 대검을 빠르게 올리고, 첫 코어로 체력과 공격력을 주는 갈라진 하늘을 가세요. 신발은 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 아트록스의 (E)\'파멸의 돌진\'과 (P)\'사신 태세\'로 인한 체력 회복을 점화의 치유 감소로 억제해야 해요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬 후 짧게 돌진하며 평타를 강화하므로, 갑자기 파고드는 거리를 조심하세요. (Q)\'혜성의 창\'을 길게 눌러 견제하되 (Q)\'교활한 휩쓸기\'의 반원 범위 끝에 맞지 않도록 주의하며 짧은 교환을 반복하세요. 첫 웨이브에서는 무리하게 붙기보다 거리 조절을 하며 체력을 깎아두는 게 좋아요.', lv3: '(W)\'배척\'은 준비하는 동안 챔피언에게 피해를 받으면 내려치는 피해가 커지니, 보호막이 켜진 동안에는 딜교환을 멈추고 기다리세요. 암베사가 (E)\'찢어 가르기\'로 둔화를 걸며 들어오면 (E)\'방패 돌격\'으로 정면 피해를 막으며 버틴 뒤 (W)\'방호의 도약\'으로 기절시켜 반격하세요. (W)\'방호의 도약\' 뒤의 강화된 평타를 섞어 짧고 강하게 치고 빠지는 구도를 만드세요.', lv6: '(R)\'공개 처형\'은 저지 불가 상태로 순간이동해 제압하니 막을 수 없고, 제압 중에는 (E)\'방패 돌격\' 같은 스킬을 전혀 쓸 수 없으니 궁극기가 있을 때는 체력을 넉넉히 유지하세요. 암베사의 궁극기가 빠진 뒤 (R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 이어가면 빠르게 압박할 수 있어요.', item: '첫 코어는 독사의 송곳니로 가서 보호막을 깎아 내는 효과로 상대가 버티는 힘을 줄이세요. 신발은 (P)\'용사냥개의 발걸음\' 강화 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'공개 처형\' 패시브로 인한 암베사의 체력 회복을 점화의 치유 감소 효과로 억제하는 게 중요해요.' },
    '애니비아': { lv1: '애니비아가 (Q)\'냉기 폭발\'을 멀리서 날려 둔화와 기절을 시도하니 옆으로 비켜 걸으며 거리를 조절하세요. 1~2레벨에는 무리하게 들어가기보다 (Q)\'혜성의 창\'을 활용해 미니언과 함께 견제하며 버티는 것이 중요해요. 애니비아가 (Q)\'냉기 폭발\'을 사용한 직후에 다가가면 딜교환을 시도하기 좋아요.', lv3: '애니비아가 (W)\'결정화\' 벽을 세워 접근을 막으려 할 수 있으니 벽이 생기기 전에 (W)\'방호의 도약\'으로 진입하세요. 애니비아의 (E)\'동상\'은 냉각 상태인 적에게 피해가 커지니 (Q)\'냉기 폭발\'을 맞은 뒤에는 거리를 두세요. (E)\'방패 돌격\'을 사용해 애니비아의 스킬 피해를 막으며 (Q)\'혜성의 창\'을 맞히는 구도를 만드세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 사용하면 범위 안에서 이동 속도가 느려지니 (E)\'방패 돌격\'으로 피해를 흘리며 대응하세요. 애니비아는 (P)\'환생\'으로 한 번 더 살아나니 (R)\'거대 유성\'으로 진입하여 (W)\'방호의 도약\'까지 연결해 확실히 압박하세요. 진입은 애니비아가 (Q)\'냉기 폭발\'을 쓴 직후에 해야 기절을 맞지 않고 붙을 수 있어요.', item: '헤르메스의 발걸음을 신발로 선택해 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 맬모셔스의 아귀를 올려 마법 저항력을 확보하고 생존력을 높이세요.', spell: '점멸과 탈진을 추천해요. 탈진으로 애니비아가 입히는 피해량을 감소시키며 거리를 좁힐 수 있어요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'으로 견제하며 (P)\'낭인의 길\' 보호막으로 피해를 흡수해요. (Q)\'혜성의 창\'을 짧게 사용해 찌르기로 맞딜을 하며, 야스오의 (Q)\'강철 폭풍\' 중첩이 쌓여 회오리바람이 날아오기 전에 거리를 조절하세요. 미니언을 타고 (E)\'질풍검\'으로 진입하려 하면 평타로 보호막을 먼저 제거하고 대응하세요.', lv3: '(W)\'바람 장막\'은 투사체를 막으므로 길게 누르는 (Q)\'혜성의 창\'은 벽이 있을 때 아끼세요. (W)\'방호의 도약\'으로 진입해 기절시킨 뒤 평타와 (Q)\'혜성의 창\' 찌르기로 빠르게 피해를 넣으세요. 야스오가 (Q)\'강철 폭풍\' 회오리를 쓰려 할 때 (E)\'방패 돌격\'을 사용하면 정면 피해를 무시하며 안전하게 딜교환을 마칠 수 있어요.', lv6: '(R)\'거대 유성\'으로 진입해 둔화를 걸면 (E)\'질풍검\'으로 도망치는 야스오를 끝까지 추격할 수 있어요. 야스오의 (R)\'최후의 숨결\'은 공중에 뜬 적 챔피언에게만 사용 가능하니 (Q)\'강철 폭풍\' 회오리에 맞지 않도록 주의하세요. 라인을 적당히 밀어두고 (R)\'거대 유성\'을 이용해 정글러와 함께 덮치는 플레이를 추천해요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 피해량을 챙기고 교전 중 체력을 회복하세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 추가 피해를 통해 (P)\'낭인의 길\' 보호막이 켜진 야스오를 빠르게 처치할 수 있어요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 공격을 하며 (P)\'바위 피부\'로 방어력을 높여요. (Q)\'혜성의 창\'으로 짧게 견제하며 오공이 평타를 많이 치지 못하게 거리를 조절하세요. 길게 싸우면 오공의 방어력이 올라가니 짧게 딜교환하고 빠지세요.', lv3: '(E)\'근두운 급습\'으로 진입할 때 (E)\'방패 돌격\'을 사용해 피해를 막아내며 공격하세요. 오공이 (W)\'분신 전사\'로 투명해지면 진짜 오공이 나타나는 방향을 예측해 (W)\'방호의 도약\'으로 기절시키세요. (W)\'분신 전사\'의 분신에 스킬을 낭비하지 않도록 주의하세요.', lv6: '(R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 오공이 휘두르기 전에 거리를 벌리세요. 오공이 (R)\'회전격\'을 사용한 뒤에 (R)\'거대 유성\'으로 진입해 둔화를 걸고 딜교환을 이어가세요. (R)\'회전격\'의 띄우기 효과는 정글러의 호응을 돕기에 강가 쪽에서는 조심해서 행동하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 보충하고 치명타 피해로 빠르게 압박하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 고정 피해로 체력이 낮은 오공을 확실하게 마무리하세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던지고 다시 불러들여서 딜을 넣으니 돌아오는 경로를 조심하세요. (P)\'영혼 방호술\'로 체력을 회복하니 1~2레벨 구간에서 무리한 딜교환보다는 (Q)\'혜성의 창\'으로 적절히 견제하며 파밍하세요.', lv3: '오로라의 (E)\'마법의 문\'은 둔화를 걸고 뒤로 뛰어오르니 이 스킬을 먼저 빼게 만드세요. (E)\'마법의 문\'이 빠진 타이밍에 (W)\'방호의 도약\'으로 진입하여 기절을 맞히고 (Q)\'혜성의 창\'으로 몰아치면 좋아요.', lv6: '(R)\'세계의 경계\' 영역 안에서는 오로라가 이동하며 괴롭히니 (E)\'방패 돌격\'으로 피해를 막으며 대응하세요. 오로라가 궁극기로 영역을 만들면 (R)\'거대 유성\'을 사용하여 빠르게 위치를 잡고 (W)\'방호의 도약\'으로 킬각을 보세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 오로라의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 가고 전투 지속력을 위해 갈라진 하늘을 선택하세요.', spell: '점멸과 점화를 추천해요. (P)\'영혼 방호술\'로 체력을 회복하는 오로라를 상대로 점화의 고정 피해와 회복 감소 효과가 필요해요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\'으로 기본 저항력이 높으니 무리하게 붙지 마세요. (Q)\'용암 균열\'의 둔화를 피하며 (Q)\'혜성의 창\'으로 가볍게 견제하세요. 첫 웨이브에서는 (Q)\'용암 균열\' 기둥이 생기는 위치를 빠르게 파악해 피하는 것이 중요해요.', lv3: '(E)\'화염 돌진\'이 지형에 부딪히면 공중으로 띄우니 벽 근처에 서지 마세요. 오른이 (W)\'불꽃 풀무질\'로 진입할 때 (E)\'방패 돌격\'으로 피해를 막아내세요. (W)\'방호의 도약\'으로 기절시킨 뒤 강화 (Q)\'혜성의 창\'을 맞춰 빠르게 딜교환을 마치세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령이 박치기하면 공중으로 띄우니 정령의 이동 경로에서 벗어나세요. 오른이 궁극기를 사용해 진입하면 (E)\'방패 돌격\'으로는 정면 피해만 막을 수 있으니 띄우기는 경로에서 벗어나 피하고, (R)\'거대 유성\'으로 거리를 조절하세요. 정글러를 불러 (W)\'방호의 도약\' 기절을 연계해 킬각을 노리세요.', item: '칠흑의 양날 도끼를 첫 코어로 가서 깎아내기 효과로 오른의 높은 방어력을 낮추세요. 신발은 마법 저항력을 주는 헤르메스의 발걸음이 좋아요. 강인함으로 (Q)\'용암 균열\'의 둔화 지속시간도 줄일 수 있어요.', spell: '점멸과 순간이동을 추천해요. 오른은 유지력이 좋고 단단해서 킬을 따기 어려우니 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력을 깎고 둔화를 걸며 접근하려고 해요. (Q)\'혜성의 창\'을 길게 눌러 원거리에서 견제하고, 올라프가 도끼를 주우러 오는 동선을 피해 거리를 유지하세요. 초반부터 무리하게 붙으면 (P)\'광전사의 분노\'로 인한 공격 속도에 밀릴 수 있으니 주의하세요.', lv3: '(W)\'방호의 도약\'으로 들어가 짧게 딜교환을 하고, 올라프가 (E)\'무모한 강타\'를 사용할 때 (E)\'방패 돌격\'으로 정면 피해를 막아내세요. 올라프의 (W)\'버티기\' 보호막이 활성화된 동안에는 피해량이 줄어드니, 보호막이 사라진 뒤에 (Q)\'혜성의 창\' 강화 공격을 맞히세요. (Q)\'역류\'를 맞지 않은 상태에서 진입해야 피해를 줄이며 교환할 수 있어요.', lv6: '(R)\'거대 유성\'으로 진입하며 둔화를 걸고 빠르게 피해를 입히세요. 올라프가 (R)\'라그나로크\'를 켜면 (W)\'방호의 도약\'의 기절이 들어가지 않으니, 무리하게 진입하지 말고 (E)\'방패 돌격\'으로 버티며 시간을 보내세요. (R)\'라그나로크\'가 끝난 직후가 가장 취약한 타이밍이니 이때 모든 스킬을 쏟아 킬각을 보세요.', item: '첫 코어는 요새파괴자로 가서 혼자 라인에 있을 때 강해지는 효과로 스플릿 압박을 키우세요. 신발은 올라프의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 올라프의 (P)\'광전사의 분노\'로 인한 회복력을 점화의 치유 감소 효과로 억제해야 해요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'으로 견제하며 (P)\'사냥꾼의 길\' 마법 피해를 입혀요. (Q)\'혜성의 창\'으로 맞견제하며 거리를 유지하고, 요네의 (Q)\'필멸의 검\' 중첩이 쌓여 돌진할 때는 옆으로 피하세요. 초반에는 짧은 딜교환 위주로 하세요.', lv3: '요네가 (E)\'영혼해방\'으로 진입하면 (E)\'방패 돌격\'을 켜서 피해를 무시하고 딜교환을 마무리하세요. (W)\'영혼 가르기\' 보호막이 사라진 뒤에 (W)\'방호의 도약\'으로 들어가 기절시킨 후 빠르게 공격하세요. 요네의 (Q)\'필멸의 검\' 돌풍을 (E)\'방패 돌격\'으로 막아내면 주도권을 가져오기 편해요.', lv6: '(R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 연계하면 킬각을 잡기 좋아요. 요네의 (R)\'운명봉인\'에 끌려와 공중에 뜨면 스킬을 쓸 수 없으니 궁극기가 빠진 것을 확인하고 싸우세요. 라인을 밀어 넣은 뒤 정글러와 함께 (R)\'거대 유성\'으로 기습해 빠르게 제압하세요.', item: '첫 코어는 요새파괴자로 가서 혼자 라인에 있을 때 강해지는 효과로 스플릿 압박을 키우세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 요네의 체력을 깎아 (W)\'방호의 도약\' 콤보로 마무리하기 좋아요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 무덤을 생성하며 체력을 회복해요. (Q)\'혜성의 창\'을 짧게 사용해 요릭의 접근을 견제하며 무덤이 쌓이지 않게 압박하세요. (P)\'영혼의 길잡이\' 망령들이 주변을 공격하니 요릭과 너무 오래 붙어있지 마세요.', lv3: '(E)\'애도의 안개\'에 맞으면 방어력이 낮아지고 망령이 몰려오니 구체를 피하는 게 중요해요. (W)\'방호의 도약\'으로 진입한 뒤 (Q)\'혜성의 창\'으로 빠르게 딜교환을 하고 (E)\'방패 돌격\'으로 요릭의 반격을 막으며 빠지세요. 요릭이 (W)\'망자의 진\' 벽을 세우면 빠르게 평타로 부수고 거리를 조절하세요.', lv6: '(R)\'군도의 장송곡\'으로 소환된 안개 마녀는 적 챔피언에게 표식을 남기고 요릭이 그 표적을 공격하면 추가 피해가 들어가니 마녀가 없는 각도에서 싸우세요. (R)\'거대 유성\'으로 진입해 요릭을 둔화시키고 빠르게 폭딜을 넣어 마녀가 개입하기 전에 처치하세요. 마녀와 망령이 라인을 빠르게 밀기 때문에 웨이브를 당겨서 정글러의 개입을 유도하세요.', item: '갈라진 하늘을 가서 체력을 보충하고 강력한 첫 타격으로 요릭을 압박하세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\' 회복량을 점화로 줄여야 킬각을 잡기 편해요.' },
    '우디르': { lv1: '우디르는 (Q)\'야생 발톱\' 태세에서 기본 공격 사거리가 늘어나고 추가 피해를 주니 거리를 조절하며 (Q)\'혜성의 창\'으로 먼저 견제하세요. 우디르가 (E)\'불길 쇄도\' 태세로 다가와서 첫 기본 공격을 맞히면 기절하므로 주의해야 해요. (Q)\'혜성의 창\'을 던져서 우디르의 체력을 미리 깎아두면 이후 딜교환이 훨씬 수월해요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막과 체력 회복을 챙기면 딜교환 효율이 낮아지니 보호막이 사라진 뒤에 (W)\'방호의 도약\'으로 진입하세요. (W)\'방호의 도약\'을 맞힌 뒤에는 (Q)\'혜성의 창\'을 꽂아 강력한 피해를 입히세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 효과에 면역이 된 상태라면 억지로 붙지 마세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용하여 주변에 피해와 둔화를 준다면 (E)\'방패 돌격\'을 사용해 피해를 막아내며 버티세요. (R)\'거대 유성\'으로 진입하면서 (Q)\'혜성의 창\'을 맞히면 우디르를 쫓아가며 압박할 수 있어요. 우디르가 (E)\'불길 쇄도\' 재사용으로 이동 불가 효과에 면역인 구간에는 (W)\'방호의 도약\'을 아껴두는 것이 좋아요.', item: '갈라진 하늘을 첫 코어로 올려서 전투 지속력을 높이세요. 신발은 우디르의 마법 피해와 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'강철 갑옷\' 회복을 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'과 (P)\'화염의 메아리\'로 원거리에서 견제하므로 정면에서 오래 버티지 마세요. (Q)\'혜성의 창\'을 던져 체력을 깎아내고, 폭약의 둔화에 걸렸을 때는 무리하게 진입하지 말고 거리를 조절하세요. (Q)\'부식성 폭약\'은 지정한 위치에 발사되니 날아오는 방향에서 옆으로 비켜서 피하며 막타를 챙기세요.', lv3: '우르곳의 (E)\'경멸\' 돌진에 맞으면 뒤로 던져지며 기절하니, 상대가 돌진할 때 옆으로 피하거나 (E)\'방패 돌격\'으로 피해를 무효화하세요. (W)\'심판의 원\'이 켜진 상태에서는 정면에서 (E)\'방패 돌격\'을 사용해 공격을 막으며 버티는 것이 중요해요. (E)\'경멸\'이 빠진 것을 확인한 뒤에 (W)\'방호의 도약\'으로 진입해 짧고 강하게 딜교환을 하세요.', lv6: '(R)\'불사의 공포\' 섬광탄이 꽂히면 체력이 낮을 때 제압되어 처형당할 수 있으니, 체력 관리에 유의하며 거리를 벌리세요. (R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 이어가면 순식간에 체력을 깎을 수 있어요. 하지만 (E)\'경멸\'에 맞으면 우르곳 뒤쪽으로 던져지니 상대 포탑 근처에서는 진입 각도를 조심하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 강력한 한 방 피해와 회복을 챙기세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 우르곳의 체력이 높으므로 점화의 고정 피해를 더해 (R)\'불사의 공포\' 처형선에 닿기 전에 빠르게 처치해야 해요.' },
    '워윅': { lv1: '1~2레벨에는 (Q)\'야수의 송곳니\'를 활용해 체력을 회복하는 워윅의 생존력이 높으니 무리하게 붙지 마세요. (Q)\'혜성의 창\'을 활용해 거리를 두며 견제하고 워윅의 체력을 미리 깎아 두는 것이 좋아요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 회복이 늘어나니 주의하며 대응하세요.', lv3: '(W)\'방호의 도약\'으로 진입해 기절시킨 뒤 (Q)\'혜성의 창\'을 맞춰 딜교환을 하고 (E)\'방패 돌격\'으로 피해를 막으며 빠져나오세요. 워윅이 (E)\'원시의 포효\'를 사용해 피해 감소를 켜고 있다면 억지로 싸우지 말고 딜을 아끼세요. (W)\'피의 사냥\' 때문에 워윅의 이동 속도가 빨라질 수 있으니 체력이 낮아진 상태에서 추격당하지 않도록 조심하세요.', lv6: '(R)\'거대 유성\'으로 둔화를 걸며 진입해 폭발적인 피해를 입히고 킬각을 노려보세요. 워윅의 (R)\'무한의 구속\'은 제압 효과라 정화로 풀 수 없으니 상대 정글러가 근처에 있다면 무리하게 싸우지 마세요. 워윅의 궁극기가 빠진 것을 확인하고 싸우는 것이 안전하며 라인을 너무 밀어 정글러의 개입을 허용하지 마세요.', item: '워윅의 마법 피해와 군중 제어 지속시간을 줄이기 위해 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템으로는 체력과 공격력을 동시에 챙길 수 있는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'의 체력 회복 효과를 억제해야 해요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복하니 미니언 근처에 서지 마세요. (Q)\'혜성의 창\'으로 거리를 유지하며 견제하고, 이렐리아가 무리하게 진입하면 평타로 대응하세요. (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 짧게 교환하고 빠지는 것이 중요해요.', lv3: '(E)\'쌍검협무\'의 두 번째 칼날이 날아올 때 길목에서 벗어나 기절과 표식을 피하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 들어오면 (E)\'방패 돌격\'으로 피해를 무시하고 역공을 가하세요. (W)\'방호의 도약\'으로 기절시킨 뒤 강화된 (Q)\'혜성의 창\'을 맞히면 짧은 딜교환에서 앞서요.', lv6: '(R)\'선봉진격검\'의 결계 안으로 무리하게 진입하지 말고, 결계 밖에서 (R)\'거대 유성\'으로 둔화를 걸며 기회를 보세요. (E)\'쌍검협무\'가 빠진 타이밍에 (W)\'방호의 도약\'으로 진입해 킬각을 잡으세요. 라인을 밀어 넣고 정글러를 부르면 (Q)\'칼날 쇄도\'의 도주 경로를 차단하기 편해요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 라이트실드 타격으로 유지력을 높이세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 이렐리아의 (Q)\'칼날 쇄도\' 회복 효과를 줄여 킬각을 잡기 편해요.' },
    '일라오이': { lv1: '1~2레벨에는 일라오이가 (P)\'고대신의 예언자\'로 소환한 촉수 근처에서 싸우지 마세요. 일라오이가 (Q)\'촉수 강타\'를 사용하기 전에 (Q)\'혜성의 창\'으로 견제하며 거리를 유지하세요. 촉수의 공격 범위에 들어가지 않도록 주의하며 라인을 관리하세요.', lv3: '일라오이의 (E)\'영혼의 시험\'에 맞으면 내 영혼이 분리되고, 일라오이가 그 영혼을 때리면 피해 일부가 나에게 들어와요. 영혼에서 너무 멀어지면 내가 숙주가 되어 촉수가 생기니 영혼 근처에서 짧게 교환하세요. (W)\'혹독한 가르침\'으로 들어올 때 (E)\'방패 돌격\'으로 피해를 막고 (W)\'방호의 도약\'으로 기절시킨 뒤 (Q)\'혜성의 창\'을 맞춰 빠져나오세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용해 촉수를 많이 소환하면 그 지역을 즉시 벗어나세요. (R)\'거대 유성\'을 사용하여 일라오이의 진입을 방해하거나 폭발적인 피해를 입힌 뒤 빠르게 자리를 피하세요. 일라오이가 촉수로 피해를 입히기 전에 (E)\'방패 돌격\'으로 공격을 흘리는 것이 중요해요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'방호의 도약\'으로 진입한 뒤 점화의 지속 고정 피해로 마무리 피해를 더해 킬각을 잡으세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 팔을 뻗어 견제하고 (P)\'세포 분열\' 조각을 흡수해 체력을 회복해요. 1~2레벨에는 (Q)\'혜성의 창\'을 길게 눌러 원거리에서 먼저 피해를 입히고, 자크가 조각을 줍기 위해 움직일 때 거리를 유지하며 압박하세요. 미니언과 겹쳐 서면 (Q)\'탄성 주먹\'으로 다른 적과 부딪혀 날아갈 수 있으니 주의하세요.', lv3: '자크가 (E)\'새총 발사\'로 진입하려 할 때 (E)\'방패 돌격\'을 사용하여 정면 피해를 무시하고 딜교환을 마무리하세요. (W)\'불안정 물질\'은 최대 체력 비례 피해를 주므로 자크가 붙었을 때 빠르게 (W)\'방호의 도약\'으로 기절시킨 뒤 빠져나오세요. (W)\'방호의 도약\'으로 진입해 (Q)\'혜성의 창\'까지 섞어 빠르게 공격하고 자크의 스킬이 빠진 틈을 노리세요.', lv6: '(R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 이어가면 킬각을 잡기 편해요. 하지만 자크의 (R)\'바운스!\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니, 자크가 튀어 오르기 전에 빠르게 진입하거나 거리를 벌리세요. (P)\'세포 분열\'로 조각이 남으면 부활하니, 적을 처치한 후 조각까지 빠르게 정리해야 해요.', item: '체력이 높은 자크를 상대하려면 방어력을 깎는 칠흑의 양날 도끼를 첫 코어로 가세요. 신발은 (W)\'불안정 물질\'의 마법 피해를 줄이고 군중 제어 지속시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'세포 분열\'을 통한 체력 회복을 억제하고 처치 확률을 높이세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'를 사용하여 두 번 공격하며 체력을 회복하니 무리한 교환은 피하세요. (Q)\'혜성의 창\'을 사용하여 자헨의 (P)\'전쟁 단련\' 중첩이 쌓이지 않도록 주의하며 대응하세요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 하면 옆으로 비켜서서 (Q)\'다르킨의 글레이브\'의 공중 띄우기를 피하세요. 자헨이 (E)\'찬란한 쇄도\'로 돌진할 때 (E)\'방패 돌격\'으로 피해를 막아내며 (W)\'방호의 도약\'으로 기절을 맞히세요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아오른 동안에는 받는 피해가 줄어드니 내려찍는 지점에서 벗어난 뒤 (R)\'거대 유성\'으로 반격하세요. 자헨의 (P)\'전쟁 단련\' 중첩이 가득 차면 부활할 수 있으니 (W)\'방호의 도약\'과 (Q)\'혜성의 창\'으로 빠르게 몰아붙여야 해요.', item: '갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 자헨의 기본 공격 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화로 회복량을 줄이세요.' },
    '잭스': { lv1: '잭스는 (Q)\'도약 공격\'으로 빠르게 접근하며 (W)\'무기 강화\'를 통해 강력한 추가 피해를 줄 수 있어요. (Q)\'혜성의 창\'을 사용하여 최대한 멀리서 잭스의 체력을 깎으며 거리를 유지하세요. 잭스가 미니언에 (Q)\'도약 공격\'을 사용해 위치가 드러난 순간에 짧게 딜교환을 시도하세요.', lv3: '잭스가 (E)\'반격\'을 켜면 판테온의 기본 공격이 모두 회피되니 평타를 아끼고 범위 밖에서 기다리세요. (E)\'반격\'이 끝나면 주변 적이 기절하니 그 순간 거리를 벌렸다가, 끝난 직후 (W)\'방호의 도약\'으로 기절시키고 (Q)\'혜성의 창\'으로 이어가세요. (W)\'무기 강화\' 평타를 맞지 않도록 스킬 사용 후에는 빠르게 거리를 조절하는 것이 좋아요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력이 올라간 상태에서는 무리하게 진입하지 마세요. (R)\'거대 유성\'으로 먼저 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 이어가세요. 잭스가 (E)\'반격\'을 켜고 있으면 끝나는 순간 기절이 들어오니 범위 밖에서 기다리세요.', item: '첫 코어는 요새파괴자로 가서 혼자 라인에 있을 때 강해지는 효과로 스플릿 압박을 키우세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 잭스가 (Q)\'도약 공격\'으로 도망가더라도 처치할 수 있어요.' },
    '제이스': { lv1: '제이스는 캐논 형태의 (Q)\'전격 폭발\'로 멀리서 계속 견제하니 구체의 궤적을 피해 움직이세요. 제이스가 평타를 치러 가까이 나오면 (Q)\'혜성의 창\'을 길게 눌러 던져 체력을 깎으며 응수하세요. 무리하게 진입하기보다 첫 웨이브에서는 체력을 보존하며 경험치를 챙기세요.', lv3: '(W)\'방호의 도약\'으로 진입해 (Q)\'혜성의 창\'으로 빠르게 피해를 입히고 (E)\'방패 돌격\'으로 상대의 반격을 막아내세요. 제이스가 (E)\'가속 관문\'을 통해 (Q)\'전격 폭발\'을 쏘면 사거리와 피해가 증가하니 빠르게 옆으로 피하세요. 해머 형태의 (E)\'천둥 강타\'로 밀쳐내기 전에 먼저 진입해 딜교환을 끝내는 것이 중요해요.', lv6: '(R)\'거대 유성\'으로 진입해 제이스를 둔화시킨 뒤 (W)\'방호의 도약\'으로 연계해 확실한 킬각을 잡으세요. 제이스가 (R)\'머큐리 캐논\'으로 변환해 첫 공격으로 방어력을 깎으려 할 때 (E)\'방패 돌격\'을 사용해 피해를 무시하세요. 라인을 밀어 넣고 궁극기의 긴 사거리를 활용해 정글러와 함께 덮치면 제이스가 빠져나가기 어려워요.', item: '첫 코어는 요새파괴자로 가서 혼자 라인에 있을 때 강해지는 효과로 스플릿 압박을 키우세요. 신발은 제이스의 기본 공격 피해를 줄여 주는 판금 장화를 맞추세요.', spell: '점멸과 점화를 추천해요. 제이스가 튼튼한 챔피언이 아니므로 점화의 강력한 피해로 킬각을 앞당기세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 지정한 지역의 적을 공중으로 띄우고 둔화시키니 스킬을 사용할 위치를 보고 범위를 피하세요. (E)\'날카로운 가시\'가 정면의 적을 둔화시키니 초가스의 정면에 서서 오래 평타를 주고받지 마세요. (Q)\'혜성의 창\'을 길게 눌러 원거리에서 초가스의 체력을 깎으며 거리 조절을 하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 쓰기 전에 (E)\'방패 돌격\'을 사용하여 마법 피해를 무시하며 접근하세요. 침묵에 걸리면 스킬을 쓸 수 없으니 맞기 전에 필요한 스킬을 먼저 쓰세요. 초가스가 (Q)\'파열\'을 사용한 직후에 (W)\'방호의 도약\'으로 파고들면 안정적으로 딜교환을 할 수 있어요.', lv6: '초가스의 (R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 주니 체력이 낮을 때는 거리를 두는 것이 중요해요. (R)\'거대 유성\'으로 먼저 진입하여 적을 둔화시킨 뒤 (W)\'방호의 도약\'으로 연계하여 빠르게 압박하세요. 초가스가 (R)\'포식\'으로 처치하여 몸집을 키우기 전에 (R)\'거대 유성\'의 강력한 피해로 먼저 승부를 보세요.', item: '첫 코어로 삼위일체를 구매하여 공격력과 체력을 챙기세요. 신발은 초가스의 마법 피해와 (W)\'흉포한 울부짖음\'의 침묵 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 고정 피해를 활용해 초가스의 체력이 낮을 때 확실하게 킬을 노릴 수 있어요.' },
    '카밀': { lv1: '카밀은 챔피언을 기본 공격하면 (P)\'적응형 방어 체계\'로 보호막을 얻어요. 1~2레벨 구간에서는 (Q)\'혜성의 창\'을 활용해 멀리서 견제하며 거리를 유지하세요. (Q)\'정확성 프로토콜\'로 이동 속도가 높아진 상태에서의 긴 교환은 피해야 해요.', lv3: '카밀의 (W)\'전술적 휩쓸기\'는 바깥쪽 절반에 맞으면 둔화와 함께 체력을 회복하니 주의하세요. (E)\'방패 돌격\'으로 피해를 줄인 뒤 (W)\'방호의 도약\'을 사용하여 기절을 시키면 좋아요. 벽 근처에서 (E)\'갈고리 발사\'로 진입하는 타이밍을 조심하세요.', lv6: '카밀의 (R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니 주의가 필요해요. (R)\'거대 유성\'을 사용하여 카밀의 위치로 떨어지며 전투를 시작하세요. 라인을 밀 때 (E)\'갈고리 발사\'에 노출되지 않도록 위치 선정을 잘해야 해요.', item: '첫 코어로 갈라진 하늘을 가서 체력과 공격력을 확보하세요. 신발은 카밀의 물리 피해를 줄여주는 판금 장화를 신어주세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'전술적 휩쓸기\'의 체력 회복을 줄이세요.' },
    '카사딘': { lv1: '카사딘이 (Q)\'무의 구체\'로 견제하며 보호막을 얻으려 할 때 거리를 조절해요. (Q)\'혜성의 창\'을 길게 눌러 던지며 상대의 체력을 깎고 미니언과 함께 압박하세요. 무리하게 붙기보다 스킬 쿨타임을 계산하며 체력을 관리해요.', lv3: '(W)\'방호의 도약\'으로 진입해 기절시킨 후 (Q)\'혜성의 창\'으로 빠르게 피해를 입히세요. 카사딘이 (E)\'힘의 파동\'을 사용해 둔화를 걸려고 하면 (E)\'방패 돌격\'으로 피해를 무효화하며 버텨요. 상대의 (W)\'황천의 검\' 강화 평타가 빠진 타이밍에 짧은 딜교환을 반복하세요.', lv6: '카사딘이 (R)\'균열 이동\'으로 빠르게 도망치거나 진입하니 (R)\'거대 유성\'의 둔화를 활용해 추격하되, 순간이동은 둔화로 막지 못함을 기억하세요. (E)\'방패 돌격\'은 정면 피해를 막아주니 스킬 타이밍을 맞춰 아껴 쓰세요. 라인을 적당히 밀어두고 정글러를 호출해 기동력이 좋은 상대를 함께 압박하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 카사딘의 마법 피해에 대응하고 강인함으로 둔화 지속시간을 줄이며 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 초반부터 강하게 압박해 카사딘이 (R)\'균열 이동\'으로 빠져나가기 전에 점화의 고정 피해로 마무리하기 위해서예요.' },
    '카시오페아': { lv1: '1~2레벨에는 카시오페아의 (Q)\'맹독 폭발\' 사거리가 길어서 거리를 유지하며 미니언을 챙겨요. (Q)\'혜성의 창\'으로 먼저 접근하기보다는 상대의 스킬을 피하며 체력을 보존해요.', lv3: '(W)\'방호의 도약\'으로 진입할 때 카시오페아의 (W)\'독기의 늪\' 위치를 확인하며 조심하세요. (E)\'방패 돌격\'으로 (E)\'쌍독니\'를 막으며 (W)\'방호의 도약\'을 맞춰 기절을 시키는 것이 좋아요. (W)\'독기의 늪\'에 들어가 이동 스킬을 못 쓰는 상황은 피해야 해요.', lv6: '(R)\'거대 유성\'을 사용하여 적에게 접근하며 둔화를 걸고 킬각을 잡아요. 카시오페아의 (R)\'석화의 응시\'를 맞으면 기절하니 등지고 있는 위치를 잡는 게 중요해요. 정글러를 불러서 (W)\'독기의 늪\' 근처에서 싸우지 않도록 주의해요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 선택해요. 카시오페아의 마법 피해를 견디고 강인함을 얻기 위해서예요.', spell: '점멸과 점화예요. (E)\'쌍독니\'를 통한 회복을 억제하고 확실하게 마무리하기 위해서예요.' },
    '케넨': { lv1: '케넨이 (Q)\'천둥의 표창\'으로 견제하며 (P)\'폭풍의 표식\'을 쌓으려 해요. 미니언 뒤에 숨어 표창을 막으며 (Q)\'혜성의 창\'을 길게 눌러 던져 거리 조절을 하세요. 표식이 두 번 쌓였다면 기절을 피하기 위해 잠시 물러나세요.', lv3: '(E)\'번개 질주\'가 빠진 순간을 노려 (W)\'방호의 도약\'으로 진입해 짧은 딜교환을 하세요. 케넨이 (W)\'전류 방출\'로 표식을 터뜨리려 하면 (E)\'방패 돌격\'으로 정면 피해를 막아내며 피해를 줄이세요. (P)\'폭풍의 표식\'이 세 번 쌓여 기절하기 전에 빠르게 공격하고 빠지세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜면 주변에 오래 머물지 말고 빠르게 거리를 벌리세요. 상대의 궁극기가 끝난 뒤 (R)\'거대 유성\'으로 진입해 둔화를 걸고 빠르게 킬각을 잡으세요. 정글러가 올 때 케넨이 (E)\'번개 질주\'로 빠져나가지 못하도록 경로를 예측해 진입하세요.', item: '월식과 헤르메스의 발걸음을 추천해요. 월식의 보호막으로 짧은 교전에서 생존력을 높이고 헤르메스의 발걸음으로 케넨의 기절 지속 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점화의 추가 피해로 체력이 낮은 케넨을 확실하게 마무리하세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 쌓이기 전까지 사거리가 짧고 몸이 약하니 적극적으로 압박하세요. (Q)\'혜성의 창\'을 길게 눌러 던지며 케일의 체력을 깎고, 케일이 (Q)\'광휘의 일격\'으로 견제하려 하면 미니언 사이에서 거리를 조절하며 받아내세요.', lv3: '(W)\'방호의 도약\'으로 케일에게 붙어 기절을 시킨 뒤 (Q)\'혜성의 창\'으로 연계하여 딜교환을 하세요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하거나 (E)\'화염주문검\'으로 반격하지 못하도록 스킬 타이밍을 잘 맞춰야 해요.', lv6: '(R)\'거대 유성\'으로 진입하여 킬각을 노리되, 케일이 (R)\'신성한 심판\'을 사용해 무적 상태가 되면 피해를 줄 수 없으니 주의하세요. 케일의 궁극기가 빠진 것을 확인한 뒤 (W)\'방호의 도약\'과 (Q)\'혜성의 창\'을 쏟아부어 격차를 벌려야 해요.', item: '첫 코어로 갈라진 하늘을 가서 교전 능력을 높이세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 케일이 성장하기 전에 빠르게 킬을 내야 해요.' },
    '코그모': { lv1: '코그모의 (Q)\'부식성 침\'이 미니언에 맞도록 미니언 뒤에 위치하여 피해를 관리하세요. (Q)\'혜성의 창\'을 활용해 적의 체력을 깎으며 거리를 조절하세요. 초반에는 무리한 진입보다 미니언을 방패로 사용하는 것이 좋아요.', lv3: '코그모가 (W)\'생체마법 폭격\'으로 사거리를 늘렸을 때 (W)\'방호의 도약\'으로 빠르게 접근하세요. (E)\'공허의 분비물\'이 남긴 둔화 장판을 주의하며 (E)\'방패 돌격\'으로 적의 공격을 막아내요. 진입 후에는 강력하게 딜교환을 시도해요.', lv6: '(R)\'거대 유성\'을 사용하여 적에게 접근하며 둔화를 걸고 (W)\'방호의 도약\'으로 기절을 시켜요. 코그모가 (R)\'살아있는 곡사포\'로 대응할 수 있으니 체력이 낮은 상태에서 무리하게 싸우지 마세요. 정글러와 함께 라인을 압박하는 것이 좋아요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 코그모의 마법 피해를 견디기 위해 마법 저항력을 확보하고 생존력을 높이기 위해서예요.', spell: '점멸과 점화. 점멸로 순식간에 거리를 좁히고 점화로 마무리 피해를 입혀요.' },
    '코르키': { lv1: '코르키의 (Q)\'인광탄\' 견제를 조심하며 적절한 거리를 유지하세요. 1~2레벨에는 무리한 진입보다 (Q)\'혜성의 창\'으로 짧게 찌르며 체력을 관리해요. 코르키의 긴 사거리에 대응하기 위해 무작정 다가가기보다 기회를 엿보며 움직여야 해요.', lv3: '(W)\'방호의 도약\'을 사용해 코르키에게 붙는 것이 중요해요. 코르키가 (W)\'발키리\'로 거리를 벌리기 전에 진입하여 (Q)\'혜성의 창\'을 맞춰야 해요. 상대가 (E)\'개틀링 건\'을 사용해 방어력을 낮추기 전에 빠르게 교전을 시작하세요.', lv6: '(R)\'거대 유성\'으로 진입하며 교전을 강제할 수 있어요. 코르키가 (R)\'미사일 폭격\'을 장전했을 때는 (E)\'방패 돌격\'을 사용하여 피해를 막으며 접근하세요. 정글러의 개입을 유도하며 라인을 당겨 관리하는 것이 좋아요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 코르키의 마법 피해를 견디고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화. 코르키의 체력을 깎아 빠르게 처치하기 위해서예요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 활용한 평타 견제가 매우 강하니, 1~2레벨 구간에는 무리하게 붙지 말고 (Q)\'혜성의 창\'을 길게 눌러 던지며 체력을 관리하세요. 퀸이 (E)\'공중제비\'로 거리를 벌리며 괴롭힐 때는 억지로 쫓지 말고 미니언 뒤에서 대기하며 기회를 보세요.', lv3: '퀸이 (Q)\'실명 공격\'을 날려 시야를 좁히기 전에 (W)\'방호의 도약\'으로 빠르게 진입해 기절을 시키세요. 퀸이 (E)\'공중제비\'로 물러나며 둔화를 걸어도 (E)\'방패 돌격\'으로 정면 피해를 막고 (Q)\'혜성의 창\'을 맞혀 피해를 입히세요. (E)\'공중제비\'를 쓴 직후가 진입하기 좋은 타이밍이에요.', lv6: '(R)\'거대 유성\'으로 퀸의 이동 경로를 예측해 떨어지면 둔화를 걸고 (W)\'방호의 도약\'으로 이어지는 강력한 콤보를 넣을 수 있어요. 퀸이 (R)\'후방 지원\'을 켜고 빠르게 이동하며 로밍을 시도한다면, 빠르게 라인을 밀어 넣거나 정글러를 불러 함께 대처하세요. (R)\'거대 유성\' 사용 후 즉시 활성화되는 (P)\'필멸자의 의지\'를 활용해 딜교환을 마무리하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 피해 회복으로 퀸의 견제를 버텨내세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 퀸의 낮은 체력을 이용해 (W)\'방호의 도약\' 진입 후 빠르게 처치할 수 있어요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 짧게 공격하며 둔화를 걸고 두 번 적중 시 끌어당겨요. (Q)\'혜성의 창\'을 길게 눌러 던지며 거리를 유지하고, 상대가 다가오면 평타와 함께 섞어 견제하세요. 1~2레벨 크산테는 (E)\'발놀림\' 보호막 외에는 버틸 수단이 적으니 적극적으로 체력을 깎으세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전할 때 (E)\'방패 돌격\'을 사용해 피해를 무효화하고 정면 공격을 막으세요. (W)\'길을 여는 자\'는 저지 불가 돌진이라 스킬로 끊을 수 없으니 맞기 전에 방패를 들어야 해요. 상대의 보호막인 (E)\'발놀림\'이 빠진 타이밍에 (W)\'방호의 도약\'으로 진입해 짧은 딜교환을 하고 빠르게 빠지세요.', lv6: '크산테가 (R)\'총공세\'를 사용하여 방어력이 낮아진 상태가 되면 (R)\'거대 유성\'으로 진입해 빠르게 피해를 입히세요. 하지만 (R)\'총공세\' 상태의 크산테는 피해량이 매우 높으니 정면에서 오래 싸우지 않도록 조심하세요. 라인을 밀어 넣은 뒤 (W)\'방호의 도약\'과 (Q)\'혜성의 창\' 콤보로 체력이 낮은 상대를 마무리하세요.', item: '첫 코어는 칠흑의 양날 도끼로 가서 방어력 감소와 스킬 가속으로 긴 교환에서 피해를 쌓으세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 상태의 크산테가 가지는 모든 피해 흡혈 효과를 억제하고 킬각을 잡기 좋아요.' },
    '클레드': { lv1: '(Q)\'혜성의 창\'으로 스칼의 체력을 깎아 클레드가 내리게 유도하세요. (Q)\'덫날리기\'에 맞았다면 끌려가지 않도록 즉시 거리 조절을 하며 뒤로 물러나세요. 1~2레벨에는 무리하게 붙기보다 원거리 견제로 체력을 깎는 것이 좋아요.', lv3: '(W)\'버럭버럭\'이 켜진 클레드와 평타 교환을 하면 위험하니 (E)\'방패 돌격\'으로 피해를 무시하며 버티세요. (Q)\'덫날리기\'가 빗나간 순간 (W)\'방호의 도약\'으로 진입해 딜교환을 하세요. (E)\'이랴!\'로 다시 돌진해 들어오는 타이밍에 맞춰 스킬을 사용하여 피해를 최소화하세요.', lv6: '(R)\'돌겨어어억!!!\'으로 돌진하는 스칼의 경로에서 벗어나 밀쳐내기를 피하세요. 클레드가 스칼에서 내린 상태라면 (R)\'거대 유성\'으로 덮쳐 빠른 딜교환으로 마무리하세요. 라인을 밀어두고 (R)\'거대 유성\'으로 다른 라인에 개입하며 영향력을 넓히세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 강력한 한 방 피해를 입히세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드를 빠르게 처치하거나 스칼의 체력을 깎아 다시 타지 못하게 압박하기 좋아요.' },
    '탐켄치': { lv1: '(Q)\'혀 채찍\'은 처음 맞는 유닛에 적중하니 미니언 뒤에 서서 피해와 둔화를 피하세요. 1~2레벨에는 (Q)\'혜성의 창\'으로 견제하되, 평타 교환을 길게 해서 (P)\'절대 미각\' 중첩이 모두 쌓이지 않게 주의하세요. 중첩이 다 쌓이면 다음 (Q)\'혀 채찍\'에 기절하므로 짧게 딜교환하고 빠지는 것이 좋아요.', lv3: '(W)\'심연 잠수\'의 표시가 보이면 즉시 범위 밖으로 벗어나 공중에 뜨는 것을 피하세요. 탐 켄치가 (E)\'두꺼운 피부\'로 보호막을 켜면 딜을 아끼고, 보호막이 사라진 뒤 (W)\'방호의 도약\'으로 진입해 기절시키세요. 정면에서 오는 공격은 (E)\'방패 돌격\'으로 막아내며 탐 켄치의 스킬을 헛쓰게 만드세요.', lv6: '(P)\'절대 미각\' 중첩이 모두 쌓인 상태에서 붙어 있으면 (R)\'집어삼키기\'에 먹혀 큰 피해를 입으니 조심하세요. (R)\'거대 유성\'으로 진입해 둔화를 걸고 빠르게 딜교환을 마친 뒤 거리를 벌리세요. 라인을 밀어 넣고 정글러를 불러 (W)\'방호의 도약\'과 연계한 확실한 CC기로 킬각을 잡으세요.', item: '칠흑의 양날 도끼를 첫 코어로 가서 방어력을 깎는 깎아내기 효과로 체력이 높은 탐 켄치를 상대하세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복 효과를 감소시키세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 둔화를 걸기 때문에 초반 맞대결이 매우 강해요. (Q)\'혜성의 창\'을 활용해 멀리서 견제하며 트런들의 체력을 깎으세요. 트런들은 (P)\'헌납\'으로 미니언이 죽을 때마다 체력을 회복하니 미니언이 많은 곳에서의 교환은 피하세요.', lv3: '트런들이 (E)\'얼음 기둥\'으로 길을 막거나 뒤로 밀어내면 접근이 어려우니 기둥 위치를 잘 살피세요. (W)\'방호의 도약\'으로 트런들을 기절시킨 뒤 (Q)\'혜성의 창\'으로 딜교환을 시도하세요. 트런들이 (W)\'얼음 왕국\'을 깔면 그 안에서는 공격 속도와 회복량이 늘어나므로 영역 밖에서 싸우는 게 좋아요.', lv6: '트런들의 (R)\'진압\'은 대상 지정 스킬로 체력을 흡수하고 방어력과 마법 저항력을 훔치니 걸어서 피할 수 없어요. 궁극기가 빠진 것을 확인한 뒤 (R)\'거대 유성\'으로 진입하고 (W)\'방호의 도약\'과 연계하면 킬을 노릴 수 있어요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 트런들의 기본 공격 피해를 줄여주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 트런들은 (P)\'헌납\'과 (W)\'얼음 왕국\'을 통해 회복이 강력하니 점화로 회복 효과를 줄이세요.' },
    '트린다미어': { lv1: '시작 단계에서는 (Q)\'혜성의 창\'으로 거리 조절을 하며 트린다미어의 체력을 깎으세요. (E)\'회전 베기\'로 갑자기 들어올 때 당황하지 말고 짧게 딜교환을 하고 빠지세요. 평타를 계속 허용하면 (P)\'격노\' 수치가 쌓여 치명타 확률이 올라가니 주의하세요.', lv3: '(E)\'회전 베기\'로 진입하는 순간에 (E)\'방패 돌격\'을 켜서 피해를 막고 역공하세요. (W)\'방호의 도약\'으로 기절시킨 뒤 (Q)\'혜성의 창\'을 맞히는 콤보를 사용하세요. (W)\'조롱의 외침\'을 맞고 등을 돌려 도망가면 둔화되니 한번 붙었으면 끝까지 교환하거나 처음부터 거리를 두세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안에는 체력이 깎여도 죽지 않으니 억지로 킬을 따려 하지 마세요. (R)\'거대 유성\'으로 둔화를 걸어 거리를 벌리거나 정글러를 호출해 함께 압박하세요. 궁극기 지속 시간이 끝나는 시점에 맞춰 다시 공격을 시작하는 것이 중요해요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 강력한 피해를 챙기세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트린다미어는 (Q)\'피의 갈망\'으로 체력을 회복하므로 점화의 치유 감소 효과가 매우 효과적이에요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 계속 견제하며 독 피해를 입히니 초반에는 최대한 맞지 말고 버티세요. (Q)\'혜성의 창\'을 길게 눌러 던져 티모의 체력을 깎으며 거리 조절을 하세요. 무리하게 다가가면 (Q)\'실명 다트\'에 맞고 평타 딜교환에서 손해를 보니 주의하세요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 것을 확인한 뒤 (W)\'방호의 도약\'으로 진입해 기절시키고 (Q)\'혜성의 창\'으로 피해를 주세요. 티모가 평타와 (Q)\'실명 다트\'로 견제할 때 (E)\'방패 돌격\'을 켜서 피해를 무시하며 다가가세요. (E)\'방패 돌격\'의 면역 시간이 끝나기 전에 딜교환을 마무리하는 것이 중요해요.', lv6: '(R)\'유독성 함정\'을 밟으면 둔화되어 추격당하기 쉬우니 티모가 버섯을 깐 위치를 잘 파악하며 움직이세요. (R)\'거대 유성\'으로 진입해 둔화를 걸고 (W)\'방호의 도약\'으로 연계해 킬각을 잡으세요. 티모가 수풀에서 (P)\'유격 전투\'로 숨어 있다면 무작정 들어가지 말고 정글러를 불러 함께 압박하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력을 높이고 피해를 복구하세요. 신발은 티모의 마법 피해를 줄이고 (R)\'유독성 함정\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 티모는 체력이 낮으니 (W)\'방호의 도약\' 이후 점화로 빠르게 마무리하세요.' },
    '피들스틱': { lv1: '1~2레벨에는 (Q)\'혜성의 창\'을 던져 견제하며 적절한 거리를 유지하세요. 상대가 시야 밖에서 (Q)\'공포\'를 사용해 기습하는 것을 막기 위해 미니언 근처에서 움직이는 것이 좋아요. 무리한 진입보다는 체력을 보존하며 경험치를 챙기세요.', lv3: '(W)\'방호의 도약\'으로 빠르게 진입해 기절시킨 뒤 (Q)\'혜성의 창\'으로 피해를 입히세요. (W)\'풍작\'의 정신 집중 상태인 적을 (W)\'방호의 도약\'의 기절 효과로 끊어주는 것이 중요해요. (E)\'수확\'의 중심부에 맞으면 침묵에 걸려 스킬을 못 쓰니, 맞기 전에 (E)\'방패 돌격\'으로 정면 피해를 막거나 범위 밖으로 비켜서세요.', lv6: '(R)\'거대 유성\'으로 진입하여 순식간에 킬각을 잡으세요. 상대가 (R)\'까마귀 폭풍\'으로 덮칠 때 (E)\'방패 돌격\'을 사용해 정면 피해를 무시하고 살아남는 것이 핵심이에요. 정글러가 개입할 때 (W)\'방호의 도약\'으로 적을 기절시켜 확실하게 처치하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높이고 강인함으로 (Q)\'공포\'와 (E)\'수확\'의 둔화 지속 시간을 줄이며 생명선 보호막으로 생존력을 높여요.', spell: '점멸과 점화. (W)\'풍작\'의 체력 회복 효과를 감소시키고 강력한 피해로 적을 빠르게 처치하기 위해서예요.' },
    '피오라': { lv1: '1~2레벨에는 피오라가 (Q)\'찌르기\'로 접근해 (P)\'치명적인 검무\' 급소를 노리니 급소 위치를 계속 확인하며 움직이세요. (Q)\'혜성의 창\'을 길게 눌러 원거리에서 견제하며 피오라의 체력을 깎아두세요. 피오라가 (E)\'대가의 검술\'을 켜고 평타를 치려 하면 거리를 벌리세요.', lv3: '(W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고 기절까지 걸 수 있으니 (W)\'방호의 도약\'을 쓰기 전 피오라의 반응을 살피세요. (W)\'응수\'가 빠진 것을 확인한 뒤 (W)\'방호의 도약\'으로 진입해 빠르게 딜교환을 하세요. 피오라가 (E)\'대가의 검술\'로 강력한 평타를 칠 때 (E)\'방패 돌격\'을 켜서 피해를 무효화하세요.', lv6: '(R)\'거대 유성\'으로 진입해 적을 둔화시킨 뒤 (W)\'방호의 도약\'으로 이어지는 콤보로 킬각을 잡으세요. 피오라가 (R)\'대결투\'를 사용하면 급소 네 군데가 모두 드러나므로 최대한 빠르게 움직여 급소를 내주지 마세요. 정글러가 올 때 (R)\'거대 유성\'으로 호응하면 킬 확률이 높아지니 라인을 적절히 관리하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 공격력을 챙기고 전투 지속력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치하고 그 주변에서 이동 속도가 올라요. 1~2레벨에는 포탑 사거리 밖에서 (Q)\'혜성의 창\'을 던져 체력을 깎으며 막타를 챙기세요. 포탑이 이미 설치된 구역에서 억지로 싸우지 말고 거리를 유지하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'에 직격당하면 기절하니 수류탄이 빠질 때까지 기다리세요. 수류탄이 빠진 순간 (W)\'방호의 도약\'으로 진입하고 (E)\'방패 돌격\'으로 정면에서 오는 (W)\'마법공학 초소형 로켓\'의 피해를 막으세요. (E)\'방패 돌격\'의 면역 시간을 이용해 최대한 피해를 줄이며 딜교환을 하세요.', lv6: '(R)\'업그레이드!!!\'로 강화된 수류탄은 범위가 넓어 위험하니, 상대가 궁극기를 쓴 직후의 스킬을 조심하세요. (R)\'거대 유성\'으로 둔화를 입힌 뒤 (W)\'방호의 도약\'으로 빠르게 접근해 킬각을 잡으세요. 포탑이 밀집된 지역보다는 하이머딩거가 단독으로 있을 때 진입하는 것이 좋아요.', item: '갈라진 하늘을 가서 체력과 공격력을 챙기고 전투 유지력을 높이세요. 신발은 (E)\'CH-2 전자폭풍 수류탄\'의 기절 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 하이머딩거는 체력이 낮아 점화의 추가 피해로 빠르게 처치할 수 있어요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_pantheon);
if (typeof module !== 'undefined') module.exports = top_pantheon;
